window.POEM_DB=window.POEM_DB||{};POEM_DB["yuan_023"]={"n":"虞集","dyn":"元","poems":[{"t":"春游","f":"七言律诗","c":["明日城东看杏花，叮咛童子蚤将车。","路从丹凤楼前过，酒向金鱼馆里赊。","绿水满沟生杜若，暖云将雨湿泥沙。","绝胜羊傅襄阳道，车骑西风拥鼓笳。"]},{"t":"至正改元辛巳寒食日示弟及诸子侄","f":"七言绝句","c":["江山信美非吾土，飘泊栖迟近百年。","山舍墓田同水曲，不堪梦觉听啼鹃。"]},{"t":"费无隐丹室","f":"七言律诗","c":["碧云双引树重重，除却丹经户牖空。","一径绿阴三月雨，数声啼鸟百花风。","年深不记栽桃客，夜静长留卖药翁。","几度到来浑不语，独依秋色数归鸿。"]},{"t":"送袁伯长扈从上京","f":"七言律诗","c":["日色苍凉映赭袍，时巡毋乃圣躬劳。","天连阁道晨留辇，星散周庐夜属櫜。","白马锦鞯来窈窕，紫驼银瓮出蒲萄。","从官车骑多如雨，祗有扬雄赋最高。"]},{"t":"送韩伯高佥宪浙西","f":"七言律诗","c":["正月楼船过大江，海风吹雨洒船窗。","云消虹蜺横山阁，潮落鼋鼍避石矼。","阙下谏书谁第一，济南名士旧无双。","湖阴暑退多鱼鸟，应胜愁吟对怒泷。"]},{"t":"挽文山丞相","f":"七言律诗","c":["徒把金戈挽落晖，南冠无奈北风吹。","子房本为韩仇出，诸葛宁知汉祚移。","云暗鼎湖龙去远，月明华表鹤归迟。","不须更上新亭望，大不如前洒泪时。"]},{"t":"寄丁卯进士萨都剌天锡","f":"五言律诗","c":["江上新诗好，亦知公事閒。","投壶深竹里，系马古松间。","夜月多临海，秋风或在山。","玉堂萧爽地，思尔佩珊珊。"]},{"t":"白鹤观","f":"七言律诗","c":["白鹤山人如鹤白，自抱山樽留过客。","要看修竹万琅玕，更对名花春雪色。","山樽本出山下泉，过客醉去山人眠。","客亦是鹤君莫笑，重来更待三千年。"]},{"t":"张令鹿门图","f":"曲","c":["张侯襄阳人，深知襄阳乐。","十年宦学怀襄阳，故托豪缣写山郭。","老我不乐思蜀都，人言嵩阳好隐居。","三十六峰常对面，水竹田庐还可图。","欲往不能心懆懆，忽见新图被山恼。","沙禽浦树俱可人，金涧石床为谁好？","向来耆旧皆英雄，驾言从之道焉从。","弄珠月冷识游女，沈剑潭深知卧龙。","八月霜晴水清浅，闻道扁舟足回转。","何时古寺傍檀溪，几处残碑在江岘。","呼鹰台高秋草多，养鱼池中莲芡波。","蜀嵩未必不如此，我今不游奈老何。","张侯张侯早结屋，莫待史詹为君卜。","要看陇上课儿耕，好在鱼梁白沙曲。"]},{"t":"赤城馆","f":"五言律诗","c":["雷起龙门山，雨洒赤城观。","萧骚山木高，浩荡尘路断。","鱼龙喜新波，燕雀集虚幔。","开户微风兴，倚杖众云散。"]},{"t":"画鹤","f":"七言古诗","c":["薛公少保昔画鹤，毛羽萧条向寥廓。","通泉县壁久微茫，故物都非况城郭。","长鸣阔步貌閒暇，解写高情亦奇作。","田中芝草日应长，石上松花晚犹落。","赤壁江深孤月小，白云野迥秋霄薄。","群帝相从绛节朝，八公许制黄金药。","误婴尘网迹易迷，移召中洲梦如昨。","借悬素壁忆真侣，忽有微风动林壑。","碧虚寥寥积雪高，直过萧台绝栖泊。"]},{"t":"家兄孟修父输赋南还","f":"七言古诗","c":["大兄五月来作客，八年不见头总白。","五人兄弟四人在，每忆中郎泪沾臆。","我家蜀西忠孝门，无田无宅惟书存。","兄虽管库实父荫，弟窃微禄承君恩。","文章不如仲氏好，叔氏最少今亦老。","五郎十岁未知学，嗟我何为长远道。","诸儿读书俱不多，又不力耕知奈何！","忧来每得二三友，看花把酒临风哦。","蜀山嵯峨归未得，盘盘先垄临川侧。","碧梧翠竹手所移，应与青松各千尺。","南风吹雪河始冰，兄归乌帽何睘睘。","明年乞身向天子，共读父书歌太平。"]},{"t":"一剪梅 春别","f":"曲","c":["豆蔻梢头春色阑。","风满前山，雨满前山。","杜鹃啼血五更残，花不禁寒，人不禁寒。","离合悲欢事几般。","离有悲欢，合有悲欢。","别时容易见时难，怕唱阳关，莫唱阳关。"]},{"t":"无俗念","f":"曲","c":["十年窗下，见古今成败，几多豪杰。","谁会谁能谁不济，故纸数行明灭。","乱叶西风，游丝春梦，转转无休歇。","为他憔悴，不知有甚干涉。","寥寥无住闲身，尽虚空界，一片中宵月。","云去云来无定相，月亦本无圆缺。","非色非空，非心非佛，教我如何说。","不妨跬步，蟾蜍飞上银阙。"]},{"t":"风入松","f":"曲","c":["画堂红袖倚清酣。","华发不胜簪。","几回晚直金銮殿，东风软、花里停骖。","书诏许传宫烛，香罗初剪朝衫。","御沟冰泮水挼蓝。","飞燕又呢喃。","重重帘幕寒犹在，凭谁寄、银字泥缄。","为报先生归也，杏花春雨江南。"]},{"t":"风入松 为莆田寿","f":"曲","c":["频年清夜肯相过。","春碧卷红螺。","画檐几度徘徊月，梁园迥，无复鸣珂。","门外雪深三尺，窗中翠浅双蛾。","旧家丹荔锦交柯。","新玉紫峰驼。","长安日近天涯远，行云梦、不到江波。","欲度新词为寿，先生待教谁歌。"]},{"t":"折桂令 席上偶谈蜀汉事因赋短桂体","f":"曲","c":["鸾舆三顾茅庐。","汉祚难扶，日暮桑榆。","深渡南泸，长驱西蜀，力拒东吴。","美乎周瑜妙术，悲夫关羽云殂。","天数盈虚，造物乘除。","问汝何如，早赋归欤。"]},{"t":"苏武慢","f":"曲","c":["云淡风轻，傍花随柳，将谓少年行乐。","高阁林间，小车城里，千古太平西洛。","瞻彼泱泱，言思君子，流水俨然如昨。","但清游、天际轻阴，未便暮愁离索。","长记得、童冠相随，浴沂归去，吟咏鸢飞鱼跃。","逝者如斯，吾衰甚矣，调理自存斟酌。","清庙朱弦，旧堂金石，隐几似闻更作。","农人告我事西畴，窈窕挂书牛角。"]},{"t":"苏武慢","f":"曲","c":["一径通幽，画屏横翠，行到白云深处。","世外蟠桃，井边佳橘，别有种萱瑶圃。","檀板轻敲，素琴闲弄，奉献凤膏麟脯。","舞翩翩、鹤发飘飘，仍是旧时仙母。","君看取、华屋神仙，满堂金玉，此是蟪蛄朝暮。","五色蓬莱，九秋雕鹗，别有出身之路。","酒熟麻姑，云生巫峡，稽首洞天归去。","任海波、清浅无时，何处绿窗云户。"]},{"t":"苏武慢","f":"曲","c":["忆昔坡仙，夜游赤壁，孤鹤掠舟西过。","英雄消尽，身世茫然，月小水寒星火。","何似渔翁，不知今古，醉傍蓼花然火。","梦相逢、羽服翩跹，未必此时非我。","谁解道、岁晚江空，风帆目力，横槊赋诗江左。","清露衣裳，晚风洲渚，多少短歌长些。","玉宇高寒，故人何处，渺渺予怀无那。","叹乘桴、浮海飘然，从者未知谁可。"]},{"t":"苏武慢","f":"曲","c":["皓月清霜，钓舟如叶，闲渡小溪澄碧。","银汉无声，玉虹横野，斗柄正垂天北。","半幅乌纱，数根华发，一緉野凫飞舄。","问回仙、城南老树，能见几何今昔。","西华顶、十丈高花，九天秋露，结就翠房瑶实。","脱屣非难，凌空何远，三咽雪融冰液。","辟谷神方，餐霞真诀，一去更无消息。","笑人间、长住虚空，谁似一轮红日。"]},{"t":"苏武慢","f":"曲","c":["扫尽风云，绰开尘土，落得半丘藏拙。","青松为盖，白石为床，一切物情休歇。","几度蓬莱，布袍长剑，闲对海波澄澈。","是谁家、酒熟仙瓢，邀我共看明月。","归去也、玉宇寥寥，银河耿耿，铁笛一声山裂。","三花高拥，九气弥罗，缥缈泰清瑶阙。","手把芙蓉，凌空飞步，今夜几人朝谒。","便翻身、北斗为杓，遍散紫瓯香雪。"]},{"t":"苏武慢","f":"楚辞体","c":["归去来兮，昨非今是，惆怅独悲奚语。","迷途未远，晨景熹微，乃命导夫先路。","风扬舟轻，候门童稚，此日载瞻衡宇。","酒盈尊、三径虽荒，松菊宛然如故。","聊寄傲、与世相违，旧交俱息，更复驾言焉取。","琴书情话，寻壑经丘，倦鸟岫云容与。","农人告我，有事西畴，孤风情棹赋诗春雨。","但乐夫、天命何疑，乘化任渠留去。"]},{"t":"苏武慢","f":"曲","c":["山月来时，海风不动，平地玉楼琼宇。","桂子飘香，露华如水，自按洞箫如缕。","杳杳冥冥，泠泠历历，青鸟解传芳语。","太微中、鸾鹤相求，尽是旧时真侣。","君听取、列豹重关，鼓雷千吏，天界更多官府。","石女簪花，木人劝酒，为我此间聊住。","高唱微吟，挥毫万丈，尘世等闲今古。","看空山、一色青青，何意断云残雨。"]},{"t":"苏武慢","f":"曲","c":["放棹沧浪，落霞残照，聊倚岸回山转。","乘雁双凫，断芦漂苇，身在画图秋晚。","雨送滩声，风摇烛影，深夜尚披吟卷。","算离情、何必天涯，咫尺路遥人远。","空自笑、洛下书生，襄阳耆旧，梦底几时曾见。","老矣浮丘，赋诗明月，千仞碧天长剑。","雪霁琼楼，春生瑶席，容我故山高宴。","待鸡鸣、日出罗浮，飞渡海波清浅。"]},{"t":"苏武慢","f":"曲","c":["六十归来，今过七十，感谢圣恩嘉惠。","早眠晏起，渴饮饥餐，自己了无心事。","数卷残书，半枚破砚，聊表秀才而已。","道先生、快写能吟，直是去之远矣。","没寻思、拄个青藜，靸双芒屦，走去渡头观水。","逝者滔滔，来之衮衮，不觉日斜风细。","有一渔翁，蓦然相唤，你在看他甚底。","便扶杖、穿起鲜鱼，博得一尊同醉。"]},{"t":"苏武慢","f":"曲","c":["十载燕山，十年江上，惯见半生风雪。","对雪无舟，泛舟无雪，不遇并时高洁。","断港残沙，今兹何夕，一似剡溪归越。","但掀篷、数尺梅花，人迹鸟飞俱绝。","君不见、五老危巅，浮丘绝顶，笑我早生华发。","返老还童，易粗为妙，定有九还丹诀。","霁景浮空，天光眩海，一体本无分别。","便堪称、六一仙公，千古太虚明月。"]},{"t":"苏武慢","f":"曲","c":["自笑微生，凡情不断，轻弃旧矶垂钓。","走马长安，听莺上苑，空负洛阳年少。","玉殿传宣，金銮陪宴，屡草九重丹诏。","是何年、梦断槐根，依旧一蓑江表。","天赐我、万叠云屏，五湖烟浪，无限野猿沙鸟。","平明紫阁，日晏玄洲，晞发太霞林杪。","苍龙腾海，白鹤冲霄，颠倒一时俱了。","望清都、独步高秋，风露洞天初晓。"]},{"t":"苏武慢","f":"曲","c":["对酒当歌，无愁可解，是个道人标格。","好风过耳，皓月盈怀，清净水声山色。","世上千年，山中七日，随处惯曾为客。","尽虚空、北斗南辰，此事有谁消得。","曾听得、碧眼胡僧，布袍沧海，直下钓丝千尺。","掣取鲸鱼，风雷变化，不是等闲奇特。","寒暑相催，乾坤不用，历劫不为陈迹。","可怜生、忘却高年，长伴小儿嬉剧。"]},{"t":"忆江南","f":"曲","c":["千岁事，何许觅松乔。","急雨轻雷开道路，星河北斗转岧峣。","相对话渔樵。"]},{"t":"忆江南","f":"曲","c":["盘石上，新画太丘翁。","扶老一枝风满袖，凌霄千岁露垂松。","不与世间同。"]},{"t":"忆江南 为陈溪山寿","f":"曲","c":["秋气至，寿斝注天香。","燕坐喜看扶两几，击鲜何必混诸郎。","长岁接宾行。"]},{"t":"忆江南","f":"曲","c":["栏干曲，正面碧崔嵬。","岚气着衣成紫雾，墨香横壁长苍苔。","柏影扫空台。","江海客，欲去更徘徊。","雾发云鬟何处在，风泉雪磴几时来。","鹤翅九秋开。"]},{"t":"南乡一剪梅 招熊少府","f":"曲","c":["南阜小亭台。","薄有山花以次开。","寄语多情熊少府，晴也须来。","雨也须来。","随意且衔杯。","莫惜春衣坐绿苔。","若待明朝风雨过，人在天涯。","春在天涯。"]},{"t":"柳梢青","f":"曲","c":["从别幽花。","玉堂金马，十载忘家。","横幅疏枝，如逢旧识，同在天涯。","荒村茅屋敧斜。","待归去、重寻钓槎。","解却丝钩，青鞋藜杖，翠竹江沙。"]},{"t":"贺新郎","f":"曲","c":["丹荔明如火。","想江城、薰风乍透，绣帘青琐。","宝篆香消初睡起，叶底流莺又过。","算几度、思归未果。","欲剪冰绡凭谁寄，恐腰围、渐减愁无那。","临岸曲，命舟舸。","凉宵冉冉银蟾度。","望清辉、千里照人，雾低云亸。","准拟雕梁栖飞燕，早晚新巢定妥。","叹会少离多似我。","留滞文园头先白，念琴心、久为芳尘锁。","将旧恨，归江左。"]},{"t":"浣溪沙","f":"七言古诗","c":["江上秋风日夜生。","萧萧两鬓葛衣轻。","芭蕉丛竹共幽情。","病骨不禁湘簟冷，梦魂犹似玉堂清。","画檐疏雨过三更。"]},{"t":"浣溪沙","f":"七言古诗","c":["风力清严扫暮烟。","纤尘不疑月婵娟。","太虚那得有中边。","大地山河空复影，九霄宫阙旧无传。","几承剑气一飘然。"]},{"t":"浣溪沙 次韵礼院孟子周佥院秋夜曲二叠","f":"七言古诗","c":["天阔秋高初夜长。","浮尘消尽雾苍茫。","澄澄孤月转危墙。","金井有声惟坠露，玉阶无色乍疑霜。","不闻人语只吟螀。"]},{"t":"烛影摇红","f":"曲","c":["雪映虚檐，梦魂正绕阳台近。","朝来谁为护重笼，云卧衣裳冷。","应念兰心薰性。","对芳年、才华自信。","洞房春暖，换羽移宫，珠圆丝莹。","板压红牙，手痕犹在余香泯。","当时惟待醉翁来，教听莺声引。","可惜闲情未领。","但雕梁、尘销雾暝。","几回清夜，月转西廊，梧桐疏影。"]},{"t":"满庭芳","f":"曲","c":["微雨经宵，暖烟笼昼，相寻闲步堤沙。","露桃风絮，香影傍乌纱。","徙倚江楼最久，绮窗迥、翠拥双丫。","轻鸥外，水村山郭，帆过泊谁家。","东华。","尘土梦，汉宫传蜡，隋树啼鸦。","记当时携手，何处天涯。","日暮清吟未足，听街鼓、催发香车。","山翁醉，惊雷散雹，深夜未停挝。"]},{"t":"鹊桥仙 寄阿里仁甫","f":"曲","c":["维舟南浦。","临流不渡。","踏破城南蔬圃。","故人直是不相忘，把酒看、沙头鸥鹭。","青云得路。","兰台乌府。","早晚新承恩露。","轻车切莫便乘风，先报与、山翁知取。"]},{"t":"蝶恋花","f":"曲","c":["昨日得卿黄菊赋。","细剪金英，题作多情句。","冷落西风吹不去。","袖中犹有余香度。","沧海尘生秋日暮。","玉砌雕栏，木叶鸣疏雨。","江总白头心更苦。","素琴犹写幽兰谱。"]},{"t":"□□□ 题梅花寒雀图","f":"曲","c":["残雪晓。","窗外幽禽小。","春声初动苔枝袅。","花落知多少。","春起早。","苦被东风恼。","绿阴青子归来早。","满径生芳草。"]},{"t":"子昂秋山图","f":"七言律诗","c":["翁昔少年初画山，丹枫黄竹杂潺湲。","直疑积雨得深润，不假浮云相往还。","世外空青秋一色，窗中远黛晓千鬟。","瀛洲鸡犬同人境，尚想翁归向此间。"]},{"t":"钓月轩（京兆杜本隶颜）","f":"五言律诗","c":["方池积雨收，新水三四尺。","风定文已消，云行影无迹。","渊鱼既深潜，水华晚还出。","幽人无所为，持竿坐盘石。"]},{"t":"味经堂诗","f":"曲","c":["维昔玄圣，有子过庭。","学礼学诗，诏之丁宁。","面墙之窒，繇不知味。","亲能使学，不能使嗜。","观于德容，听于德音。","咏歌周旋，实悦我心。","邈乎千载，圣往言在。","舍而不求，匪罔斯殆。","畏友翚父，穷经笃行。","既有诸躬，思贻厥成。","既菑既畬，俾稼之食。","既畋既渔，俾鼎之实。","作堂高明，曰子远来。","吾经在兹，远其味之。","始予虚羸，匍匐来食。","茹草饮水，以禦朝久。","穷人得归，自我父师。","俛焉斯文，老至不知。","煌煌灵芝，如彼嘉玉。","薄言采之，在彼中谷。","南阳之人，来詹来言。","君子岂弟，宜其后昆。"]},{"t":"题宋诚甫侍郎垂纶亭","f":"曲","c":["岷源建高，驶无游舠。","汉会其委，安流滔滔。","爰有君子，垂纶其下。","虽不得鱼，意甚閒暇。","援藟引楫，至于中沱。","荫树以休，悠悠永歌。","逝波沄沄，不转维石。","乐兹忘忧，矢言不食。","烝然云兴，风举以高。","鹤翔中天，遗景九皋。","木其落矣，鱼亦潜渚。","眷言夙好，除于风雨。","风吹衣裳，彼为栖栖。","行吟望予，实劳我思。","山有榛棘，河有鳇鲤。","岂其饮泉，必泠之美。","君子冠纯，秩秩大经。","泂有清酌，可以濯缨。"]},{"t":"高竹临水上","f":"五言律诗","c":["高竹临水上，幽花在崖阴。","以彼贞女姿，当此君子心。","春阳不自媚，夕露忽已深。","湘妃昔鼓瑟，怅望苍梧岑。"]},{"t":"月出古城东","f":"五言律诗","c":["月出古城东，海气浮空濛。","车骑各已息，宫阙何穹窿。","牧马草上露，吹笳沙际风。","帐中忽闻雁，传令彀雕弓。"]},{"t":"书上京国子监壁","f":"五言古诗","c":["神京极高寒，幽居了晨夜。","雷风无时发，零雨每飘洒。","炎光不到地，萧爽度长夏。","大化漠无宰，岂必事陶冶。","扬雄不晓事，守道栖栖者。","玄经百无徵，白发谩盈把。"]},{"t":"至治壬戌八月十五日榆林对月","f":"五言古诗","c":["日落次榆林，东望待月出。","大星何煜煜，芒角在昴毕。","草树风不起，蛩蜩绝啁唧。","天高露如霜，客子衣尽白。","羸骖龁馀栈，嫠妇泣幽室。","行吟毛骨寒，坐见河汉没。","驿人告晨征，曈曈晓光发。"]},{"t":"忆三十年前与元复初参政同赋秋日梨花元有句云朝食叶底梨暮看枝上花而忘其后句因续之云","f":"五言律诗","c":["朝食叶底梨，暮看枝上花。","花开食实后，霜风振长柯。","远水良可鉴，彩云亦易过。","念尔白于雪，日暮当如何？"]},{"t":"李老谷","f":"五言古诗","c":["十转山崦交，九度沙碛溜。","始辞平漠旷，稍接山木秀。","老病畏行役，慰藉得良觏。","秋岭晚更妍，寒花昼如绣。","故园夫如何？","朝阳眩霜柚。"]},{"t":"泰定甲子上京有感次韵马伯庸待制","f":"五言律诗","c":["翰音迎日毂，仪羽集云路。","寂寞就书阁，老大长郎署。","为山望成岑，织锦待盈度。","我行起视夜，星汉非故处。"]},{"t":"天历戊辰前续咏贫士一首","f":"五言古诗","c":["目昏畏附火，枯坐寒窗中。","破褐著絮重，虚豆兼冰崇。","病骨于此时，浮屠屹撑空。","呼儿检馀历，记日待春风。","虽欣解冻近，翻惊纪年穷。","贳酒欲自广，无钱似陶翁。"]},{"t":"后续咏贫士三首 其一","f":"五言古诗","c":["老骨寒不寐，夜长况闻风。","心悸危欲折，局蹐败絮中。","鸡鸣当晨参，马疥刍不充。","山童衣百鹑，唤之愧匆匆。","求火扫木叶，庭树亦已空。","决起不敢怠，曙光屋南东。","苟遂牛马性，归放春草丰。"]},{"t":"后续咏贫士三首 其二","f":"曲","c":["归蜀越关陇，栈阁危登天。","适越河济隔，堰水丈尺间。","饥寒迫旦暮，舟车计茫然。","东家有一叟，欲去初不言。","早朝听诏毕，唤马阊阖前。","童奴受宿戒，向煖争相先。","闻之嗔儿子：我何为汝牵？","屦无千金贾，吾足安暇怜。"]},{"t":"后续咏贫士三首 其三","f":"五言古诗","c":["为政贵察色，读书在研覃。","司视既不明，两者无一堪。","尚不逭吏责，为师固宜惭。","圣世无弃物，况兹久朝簪。","决去岂我志，知止亦所谙。","颇闻南山下，菊根浸寒潭。","濯饵千日期，冰胪复清涵。","老马果识道，更服盐车骖。"]},{"t":"观花有感","f":"五言律诗","c":["挂巾花树枝，酌酒花树下。","风吹巾上尘，花落手中斝。","清唱起相寿，毋遽且聊暇。","流光急去人，莫怪行乐者。"]},{"t":"同阁学士赋金鸭烧香","f":"五言律诗","c":["黄金铸为鸭，焚兰夕殿中。","窈窕转斜月，逶迤动微风。","绮席列珠树，华灯连玉虹。","无眠待顾问，不知清夜终。"]},{"t":"退直同柯敬仲博士赋","f":"五言律诗","c":["月下白玉阶，露生黄金井。","疏条栖鹊寒，衰蕙流萤冷。","恋阙感时康，怀归觉宵永。","晨钟禁中来，白发聊自整。"]},{"t":"题儋耳东坡载酒堂二首 其一","f":"五言古诗","c":["翳翳儋耳城，历历桄榔树。","百年遗故丘，新堂设宾阼。","清风海上至，朝阳在庭户。","丹山五色凤，览德屡来下。","甘辛熟桂酒，罗列杂藷蓣。","苻黎多孙子，食饮祭先具。","蛟龙波浪深，归来风雨除。"]},{"t":"题儋耳东坡载酒堂二首 其二","f":"五言古诗","c":["凿井得甘泉，渴者恒自私。","流润不择地，委顺复何疑。","海南绝风雨，水木况华滋。","邻舍解读书，诸生还诵诗。","何必怀故都，聊乐宜在兹。","星河度白鹤，山月悬蛾眉。","来晚去何速，劳人千载思。"]},{"t":"盗发亚父冢","f":"五言古诗","c":["盗发亚父冢，宝剑实累之。","冢开宝气尽，狱吏书盗辞。","盗言惟见宝，宁知亚父谁？","项王不相信，弟子遂舆尸。","黄肠下深锢，千岁复何为。","大河绕城东，落日在城西。","过客立城下，踟蹰望安期。","朱光出东海，高台迎赫曦。","六龙献阳燧，九凤保金支。","鍊丹轩辕鼎，濯景昆崙池。","拜赐冰玉佩，玄洲共遨嬉。"]},{"t":"步虚词","f":"五言律诗","c":["步虚长松下，流响白云閒。","华星列爟火，明月悬佩环。","肃然降灵气，穆若愉妙颜。","竹宫憺清夜，望拜久乃还。"]},{"t":"记子昂画","f":"五言律诗","c":["春风动兰叶，庭户光陆离。","言收竹上露，石角挂綀衣。","车行不择路，芣苡何楚楚。","游子憺忘归，徘徊岁云暮。"]},{"t":"送西台治书仇公哲","f":"五言古诗","c":["陕郊得时雨，生意始来复。","存者事稼穑，还者葺墙屋。","安知凋瘵馀，政可致新福。","辟除正广术，区井表深渎。","均齐定恒志，忠厚保敦笃。","岂无忧世士，受仕在刍牧。","为义苦多违，好名常不足。","治书肃将指，善类庶有勖。"]},{"t":"送张道士归上清","f":"五言律诗","c":["白云旴水上，自古多仙人。","手携绿玉杖，头戴白纶巾。","袖中出风雨，天上礼星辰。","归来庭户静，芳草自生春。"]},{"t":"日出行","f":"五言古诗","c":["日出上城府，日暮当早归。","城门已击柝，出郭何焉依？","下马投馆人，空垣月当扉。","凉风振庭树，巢鸟屡惊飞。","起坐搔白发，忽如霜草稀。","周公不复梦，仲尼故沾衣。","老莱有孺色，传闻惟食薇。","求之事已晚，徘徊行道微。"]},{"t":"赠写真佟士明","f":"五言古诗","c":["佟郎居上京，阅人如风花。","拈笔写其似，千岁留英华。","迩来七十年，将相纷在目。","来者有如此，往者那可续。","昔我初北游，面白鬓如鸦。","点染烦粉墨，华星映丹霞。","今如雪中松，苦硬杂苍白。","却视当年容，邈如不相识。","不识当如何？","临风且长歌。","黄云接河汉，白雪漫陂陀。","乞身愿归老，吴蜀山总好。","赠君千黛螺，翠色秋可扫。"]},{"t":"寄陈众仲助教上都作","f":"五言律诗","c":["学省足清昼，词垣惊早秋。","美人隔河汉，落月在高楼。","持衣未成曲，吹笛不胜愁。","还趋鳷鹊观，别制鹔鹴裘。"]},{"t":"题商德符华山图","f":"五言古诗","c":["昔祠云台馆，行穿御阶柏。","夕阴岚气深，重碧照行客。","独访张超谷，渐觉岩险迫。","冰生玉井头，日射仙掌侧。","岂无铁锁悬，翻身若飞鹘。","恐烦华阴令，不奈昌黎伯。","王事况有程，车马何忽忽。","流观终南山，周览天府国。","尔来十七年，欲往不再得。","山河想邈悠，伤残转萧索。","摩挲商老图，彷佛希夷宅。","高哉莲华峰，白云澹秋色。"]},{"t":"赋茅山道士云松巢","f":"五言古诗","c":["昔年李太白，庐山思结巢。","褰云自天上，和鹤止松梢。","道士潘闲远，高居古大茅。","诵经门卧虎，看剑石眠蛟。","飞步脱凫舄，长吟吹凤匏。","九江揽秀色，许尔作神交。"]},{"t":"题李溉之学士白云半閒","f":"五言古诗","c":["山中多白云，何由到城邑。","招之恐不来，欲揽遽无迹。","栖檐候晨光，纳牖作秋色。","用冲不为盈，常住宁若客。","分张任苍松，散落还白石。","日照香炉峰，月射仙掌侧。","有恩封一乡，与子当共食。"]},{"t":"为范尊师赋云林清游","f":"五言古诗","c":["太茅千仞下，结屋三四楹。","云林户牖润，鹤去海天平。","坐上发长啸，人间闻玉笙。","斸苓春雾重，煮朮晚烟轻。","绿室嘘丹气，苍崖受日精。","樵遗伐木斧，真降引霓旌。","九鼎金还就，千龄树不倾。","问谁解居此，云是范长生。"]},{"t":"送李彦方闽宪","f":"五言古诗","c":["七闽去天远，颠连苦无告。","牧人受深寄，昧者覆为暴。","犀象杂金贝，饥渴剧饫膏。","大言相鄙夷，餍夺心自恔。","岂无循廉吏，实病黑白挠。","聪明属旒黈，听荧资所到。","李侯金闺彦，图史擅雠校。","晨闻大夫奏，夕理武夷棹。","君子慎修职，宁适丰廪稍。","蕉荔甘多毒，姜桂老堪芼。","所怀延平翁，扬休似明道。","授受有源委，精微足深讨。","言立圣如在，表正愚可造。","师匠久不兴，真妄如枘凿。","云何诮支离，肆诞长凶傲。","异言古所诛，末学足深悼。","闽虽在海隅，前闻此渊奥。","正谊从简编，良俗宜善导。","赠言不及他，持此永为好。"]},{"t":"题郑秀才隐居","f":"五言古诗","c":["陶翁昔好菊，荒径不暇锄。","素琴初无弦，名酒亦屡虚。","虽有二三子，薪水不读书。","凄凉千载下，高名将焉如。","不如鬼谷洞，郑子乐有馀。","种菊以为田，田中更为庐。","善药不二价，咏觞送居诸。","有子挥五弦，凉风在庭除。","时来青田鹤，亦出濠梁鱼。","昨者游京师，侯门曳华裾。","捧檄忽一喜，翩然告归与。","芳蒲采甘露，玉浆酿清醑。","老父坐堂上，稚子具篮舆。","晨游南山陲，暮濯清水渠。","席閒抚猗兰，房中咏《关雎》。","以此得高寿，何必南阳居。"]},{"t":"题朱邸竹木","f":"五言古诗","c":["猗猗淇园竹，结根盘石安。","枝干相扶持，风雨不可干。","其实凤所食，君子思保完。","恒恐声影疏，萧条霜露寒。","金玉慎高节，千载承清欢。"]},{"t":"咏史","f":"五言古诗","c":["轩后邈已远，汉武亦雄哉。","荒忽九州外，百年过烟埃。","变化庶长久，临海筑层台。","黄金靡镂饰，乔林摧断裁。","乐通竟先死，孙卿殊未回。","不知作者意，空令来者哀。","奉盘泣繁露，驰道殷奔雷。","志气昔所在，风云恒往来。"]},{"t":"赋苏伯修滋溪书堂","f":"五言古诗","c":["滋源恒伏流，春雨川乃盈。","林畴广敷润，草木俱繁荣。","临深见游鯈，仰乔有鸣莺。","君子乐在斯，斋居托令名。","积学抱沈默，时至有攸行。","抽简鲁史存，采诗商颂并。","禹穴追马公，湘江歌屈生。","纫兰不盈握，伐木有馀情。","浩然欲浮海，归兴还濯清。","方舟我为楫，白发愧垂缨。"]},{"t":"送张兵部孟功巡河分题得屋上乌","f":"五言律诗","c":["花发上阳春，门开未央曙。","城柝起群栖，流光散朝羽。","息影须近檐，结巢愿当户。","辘轳转金井，终日灌嘉树。"]},{"t":"赋水木清华亭","f":"五言律诗","c":["中流泛兰枻，望彼嘉树林。","落日荡野水，浮云生夕阴。","游鱼恋芳藻，好鸟鸣幽岑。","为乐恐易老，吾将脱朝簪。"]},{"t":"于仲元舍赋红梅","f":"五言律诗","c":["白雪不成夜，丹霞遂崇朝。","妙质承日映，飞英向风飘。","醉来红袖近，歌罢綵云消。","扬州问何逊，何似董娇娆？"]},{"t":"赋洛川老人九十","f":"七言古诗","c":["洛川老人年九十，须眉如画身玉立。","锦袍金带方乌巾，手挽强弓无决拾。","八月平原秋气高，闻有狡兽依蓬蒿。","清晨上马薄暮返，累骑毛血悬鞬櫜。","身是前朝将家子，生逢太平百无事。","都将英气化高年，何物小儿堪指使。","太守上言朝有恩，束帛养牛兼上尊。","洛川老人过百岁，击壤为歌传子孙。"]},{"t":"湛湛行","f":"七言律诗","c":["湛湛天宇玄以黝，星白如银垂近人。","牛羊散漫草多露，大帐中野傍无邻。","去年八月羽书急，妇女上马小儿泣。","今年八月天子来，身属櫜鞬月中立。"]},{"t":"子昂墨竹","f":"七言古诗","c":["子昂画竹不欲工，腕指所至生秋风。","古来篆籀法已绝，止有木叶雕蚕虫。","黄金错刀交屈铁，大阴作雨山石裂。","蛟龙起陆真宰愁，云暗苍梧泣湘血。","吴兴之竹乃非竹，吴兴昔年面如玉。","波涛浩荡江海空，落月年年照秋屋。"]},{"t":"商德符画幽篁古木","f":"七言律诗","c":["湘君宫在洞庭湖，幽篁古木龙所都。","石坛雨长碧苔藓，水屋风动青珊瑚。","老人攲枕看蝼蚁，嫠妇停舟听鹧鸪。","江南蜀道问来往，商公商公今有无？"]},{"t":"为达兼善御史题墨竹","f":"七言古诗","c":["蜀道荒凉多古木，筼筜千尺相因依。","小年惯见今白发，杜宇夜啼愁不归。","老可尝作陵州守，古墨蛟龙多入手。","春雷每恐破壁去，神鼎空令夔魅走。","丹丘越人不到蜀，脩叶何以能纵横。","内府人家烂熳写，使可见之心亦惊。","江南御史龙头客，暂别那能不相忆。","知君深识篆籀文，故作寒泉溜崖石。"]},{"t":"写庐山图上","f":"七言律诗","c":["忆昔系船桑落洲，洲前五老当船头。","风吹云气迷谷起，霜堕枫叶令人愁。","高人祇在第九叠，太白一去三千秋。","石桥二客如有待，裹茶试泉春岩幽。"]},{"t":"题旦景初佥司画","f":"七言古诗","c":["旦公山堂城东南，画图古桧何毵毵。","城中无山有山癖，直藉豪墨穷幽探。","旦公弹琴古桧下，郁郁窗户生晴岚。","春雨时来鹤鸣谷，秋声夜作龙吟潭。","先皇昼坐群玉府，内使趣召飞双骖。","毕宏韦偃出中秘，营丘北苑开縢缄。","是时旦公主舒卷，一二文士相交参。","旦公归来坐成想，亦颇拈笔为楩楠。","伯熙奉诏每有作，礧砢相并将无惭。","嗟予怀归亦已久，摩挲老目百不堪。","山中岂乏真偃蹇，可容白发抽朝簪。"]},{"t":"题柯敬仲画","f":"七言古诗","c":["昔者老可守陵州，守居北山吾故丘。","太守时来看山雨，每画纸背成沧洲。","老蒲松烟色过重，挥霍阴崖交剑矛。","百年离乱亡故物，敝箧江南谁复收。","新图筼筜枝叶脩，使我不乐思昔侯。","碧鸡祠前杜鹃叫，玉女井上丛篁幽。","棠梨树高青子落，碧花翠蔓萦牵牛。","扬雄无家不归老，蟏蛸蟋蟀寒相求。","丹丘先生东海客，何以见我空山秋。","萧条破墨作清润，残质刊落精英留。","陂陁重复分细草，山石萦纡生乱流。","眉山学官莫厌冷，言归故乡非远游。","石田茅屋傥可得，万里欲上东吴舟。","百花潭深濯新锦，持报以比珊瑚钩。"]},{"t":"白翎雀歌","f":"曲","c":["乌桓城下白翎雀，雌雄相呼以为乐。","平沙无树托营巢，八月雪深黄草薄。","君不见旧时飞燕在昭阳，沈沈宫殿锁鸳鸯。","芙蓉露冷秋宵永，芍药风暄春昼长。"]},{"t":"题简生画涧松","f":"七言古诗","c":["简生与我皆蜀人，留滞东南凡几春。","每拂齐纨作山水，使我感慨怀峨岷。","如此长身两松树，满谷悲风散阴雾。","雌雄如剑变为龙，鳞鬣齐成擘崖去。","秘阁尝观韦偃图，苍润雄深世所无。","默识形神出模画，把笔莽苍增嗟吁。","玉堂宝书本同馆，官府既分难复见。","摩挲新墨慰衰朽，鬓雪飘萧数开卷。","昔我樵牧青城山，坐起政在双树间。","当时简生若相见，应并写此听潺湲。","刘郎集贤好宾客，好著幽窗对晴碧。","凌灵为我哦七言，有鹤飞来破秋色。"]},{"t":"题柯博士画","f":"七言古诗","c":["矶头风急潮水长，蒹葭苍苍系鱼榜。","青山一发是江南，白头不归神独往。","幽篁绕屋茅覆檐，木叶脱落秋满帘。","买鱼沽酒待明月，定是黄州苏子瞻。","子瞻文章世希有，谪向江波动星斗。","夜投断岸发清啸，栖鹘惊飞怒蛟吼。","图中风景偶相似，欣然挥洒春云开。","子瞻应是念乡里，还化江东孤鹤来。"]},{"t":"题高彦敬尚书赵子昂承旨共画一轴为户部杨侍郎作","f":"七言古诗","c":["不见湖州三百年，高公尚书生古燕。","西湖醉归写古木，吴兴为补幽篁妍。","国朝名笔谁第一？","尚书醉后妙无敌。","老蛟欲起风雨来，星堕天河化为石。","赵公自是真天人，独与尚书情最亲。","高怀古谊两相得，惨淡酬酢皆天真。","侍郎得此自京国，使我观之三叹息。","今人何必非古人，沦落文章付陈迹。"]},{"t":"题滦阳胡氏雪溪卷","f":"七言律诗","c":["积雪平沙阴山道，射虎残年不知老。","岂识船如天上坐，翠竹为帷树为葆。","昔乞镜湖苦不早，白发如丝照清潦。","他年此地若相逢，应著渔蓑脱貂帽。"]},{"t":"题杨友直检校所藏李营丘枯木图","f":"七言律诗","c":["老龙出海苍髯须，营丘枯木天下无。","回枝屈铁堕崖雪，涧底应拾青珊瑚。","明堂清庙要梁栋，朔风吹沙泽腹冻。","老身不用叹迟暮，按图来求万钧重。"]},{"t":"酬萧侯送蒲萄","f":"七言古诗","c":["萧侯昔致蒲萄苗，山童不灌三日焦。","宛西上品复亲致，手种窗南自浇水。","一月当生一尺长，移向江头薜荔墙。","秋深雨足马乳重，举囊石压青霞浆。","是时萧侯当走马，来访衰翁茅屋下。","酒酣舞剑倾一尊，不信金盘露如泻。"]},{"t":"题衮尘骝图","f":"曲","c":["骅骝食粟石每既，立仗归来汗如洗。","脱羁展转聊自恣，落花尘土随身起。","君不见春雷起蛰龙欠伸，雾拥云蒸九河水。"]},{"t":"林皋亭","f":"五言律诗","c":["九月天气肃，鹤鸣在林阴。","使君甚好客，来者总能吟。","红树秋山近，黄华夕露深。","邻翁八九十，有酒即相寻。"]},{"t":"题子昂长江叠嶂图","f":"五言律诗","c":["昔者长江险，能生白发哀。","百年经济尽，一日画图开。","僧寺依稀在，渔舟浩荡回。","萧条数根树，时有海潮来。"]},{"t":"送先陇二邻僧还吴","f":"五言律诗","c":["兰若背山阴，松筠夹径深。","门閒容虎卧，湖近听龙吟。","雨过泉添涧，风飘磬出林。","衲衣皆旧识，一一谢幽岑。"]},{"t":"次韵阿荣存初参议秋夜见寄","f":"五言律诗","c":["寓馆城门夕，高秋雨露开。","天垂华盖近，月转紫垣来。","疏阔思良会，淹留到不才。","深期谢安石，挥麈散风埃。"]},{"t":"雪谷早行","f":"五言律诗","c":["积雪拥柴门，行人稍出村。","溪头或遇虎，木末不闻猿。","接栈回山阁，支桥就树根。","驱车上重坂，回首见朝暾。"]},{"t":"雪岩楼观","f":"五言律诗","c":["高阁丹青起，中天紫翠分。","窗当太白雪，门俯九疑云。","伐木山人去，吹箫帝子闻。","尘中归未得，春思转纷纷。"]},{"t":"送人之剑阁倅","f":"五言律诗","c":["往年登剑阁，快马著春衫。","设险怀前赋，摩崖觅旧劖。","乡人游雪界，郡倅试冰衔。","归道观新政，春江不挂帆。"]},{"t":"寄子山尚书","f":"五言律诗","c":["竹色侵衣碧，重帘雨气深。","白鹅翻墨沼，紫燕入书林。","北海春尊侧，西山夕阁阴。","东曹公事少，歌舞散黄金。"]},{"t":"漫兴","f":"五言律诗","c":["雨阁添衣润，风帘隐几高。","白头更事少，病目向书劳。","南客传音信，东家问酒醪。","江边茅屋破，归楫若为操。"]},{"t":"送张尚德","f":"五言律诗","c":["六月初闻雨，官河潦水生。","江南归宋玉，稷下谢荀卿。","雕鹗青霄迥，蒹葭白露盈。","都留诗兴在，来听上林莺。"]},{"t":"明皇按乐图","f":"五言律诗","c":["新度《霓裳曲》，三年教得成。","惊鸿浑不下，飞燕若为轻。","芍药春亭暮，芙蓉野水生。","梨园多白发，吹笛到天明。"]},{"t":"送长沙守","f":"五言律诗","c":["白发长沙守，循良又好文。","近辞金马去，远有玉鱼分。","对竹听湘雨，开帘看岳云。","汉廷思贾谊，一饭莫忘君。"]},{"t":"代众仲作","f":"五言律诗","c":["昔在泉州住，将军每见招。","春云山对屋，夜雨水平桥。","池鸭穿荷叶，溪鱼上柳条。","禁城钟鼓起，车马晚萧萧。"]},{"t":"送王照磨之官云南","f":"五言律诗","c":["遗庙珍珠浦，归舟僰道溪。","飞鸢愁暑雨，走马畏山泥。","官署尊丹鹫，祠官胜碧鸡。","题诗远相送，红日五云西。"]},{"t":"玉堂燕集图","f":"五言律诗","c":["朝廷多暇日，别馆又青春。","薄醉犹催酒，清歌况有人。","玉堂金砚匣，翠袖白纶巾。","老去浑无赖，凭谁为写真。"]},{"t":"画桧","f":"五言律诗","c":["茅山多古树，此桧更长生。","鹳鹤栖来稳，蛟龙化得成。","云深还近户，月落似闻笙。","千载如相见，苍然故旧情。"]},{"t":"赠杨友直","f":"五言律诗","c":["洛阳杨友直，字儗汉中郎。","画若锥穿石，垂如雨漏墙。","舞花羞女美，醉草笑僧狂。","昨日鸿都学，烦君写数行。"]},{"t":"题朱邸竹木","f":"五言律诗","c":["江上复春雨，层阴覆碧波。","石高龙影卧，林迥鹤声过。","解佩猗兰浦，扬旌落木坡。","佳人翠袖薄，日暮欲如何？"]},{"t":"赤壁图","f":"五言律诗","c":["过鹤生新梦，携鱼忆旧游。","清霜凋木叶，落月涌江流。","隐者时堪访，良田亦易求。","如何玉堂夜，白发不胜愁。"]},{"t":"八月八日有感题视草堂壁","f":"五言律诗","c":["载笔趋芸阁，探囊索缊袍。","坐销秋日净，心折夜风高。","识字头先白，谋生计转劳。","文园多病渴，常想赐蒲萄。"]},{"t":"赋程氏竹雨山房二首 其一","f":"五言律诗","c":["春雨过山竹，幽泉绕舍鸣。","燕泥书帙晚，鱼浪钓丝晴。","奉席从孙子，连床总弟兄。","旧闻林下叟，读《易》到天明。"]},{"t":"赋程氏竹雨山房二首 其二","f":"五言律诗","c":["游子闻春雨，思亲望故园。","竹间开几席，花底注山尊。","累世书连屋，频年稻满村。","卜邻淳朴地，绝学欲重论。"]},{"t":"戏作试问堂前石五首 其一","f":"五言律诗","c":["试问堂前石，来今几十年？","衰颜空雨雪，幽致自风烟。","微醉寒堪倚，孤吟静更眠。","旧湖春水长，谁系钓鱼船。"]},{"t":"戏作试问堂前石五首 其二","f":"五言律诗","c":["为问堂前石，何年别太湖？","春风神不王，夜月影长孤。","不中明堂柱，空馀艮岳图。","颇思嘉种木，岁晚与相扶。"]},{"t":"戏作试问堂前石五首 其三","f":"五言律诗","c":["为问堂前石，何无藤蔓缠？","金莲疑可致，紫菊若为妍。","旧梦遗波浪，閒情阅岁年。","祇缘相识久，亲为濯清泉。"]},{"t":"戏作试问堂前石五首 其四","f":"五言律诗","c":["碣石久沦海，女娲曾补天。","乾坤遗蕞尔，雾雨护苍然。","淬剑龙随化，弯弓虎自全。","昔贤多赋此，谁赋最流传？"]},{"t":"戏作试问堂前石五首 其五","f":"五言律诗","c":["为问堂前石，屡逢堂上人。","远来嗟最久，独立与谁邻？","运载劳车马，摩挲识凤麟。","銮车书吉日，追琢到嶙峋。"]},{"t":"代石答五首 其一","f":"五言律诗","c":["幸自邻顽鄙，毋烦问岁年。","当寒金作砺，向煖玉生烟。","眉黛无归意，毛群有叱眠。","凉州三百斛，亦未酹觥船。"]},{"t":"代石答五首 其二","f":"五言律诗","c":["昔观一柱观，还度几重湖。","雪尽身还瘦，云生势不孤。","研穿邺台瓦，赋就草堂图。","芝阁玄云在，危踪敢藉扶。"]},{"t":"代石答五首 其三","f":"五言律诗","c":["牛角何堪砺，蜗涎谩自缠。","沈冥辟邪古，羞涩望夫妍。","神物须清鉴，灵根属小年。","金舆曾共侍，千载忆甘泉。"]},{"t":"代石答五首 其四","f":"五言律诗","c":["转徙宁论地，存留亦信天。","露盘危欲折，劫火不同然。","洛下残经断，岐阳数鼓全。","向无文字托，寂寞竟谁传？"]},{"t":"代石答五首 其五","f":"五言律诗","c":["去岁留诗别，嗟哉白发人！","冠依子夏制，居切左丘邻。","执籥充振鹭，脩辞缀获麟。","终须愁坎壈，勿用诮嶙峋。"]},{"t":"送鲁子翚廉使之汉中","f":"五言律诗","c":["封上颂台礼，轻车入汉中。","节毛吹渭雨，木叶动秦风。","把酒台基古，驰书岁事丰。","朝回倚西阁，日日数归鸿。"]},{"t":"立春夜试墨","f":"五言律诗","c":["轻雪作春花，飞来入鬓斜。","紫貂迎晓雾，绛蜡炫晴霞。","书诏频趋阁，思归即借车。","几时将稚子，随意踏江沙。"]},{"t":"次韵筠轩司徒足成旦公所藏英宗御题之句元题曰日光照吾民月色清我心又题琴曰至治之音二首 其一","f":"五言律诗","c":["化国多长日，高人侍紫宸。","观书从上相，属笔念生民。","云汉文章备，风雷号令新。","惟应青简在，能载古风淳。"]},{"t":"次韵筠轩司徒足成旦公所藏英宗御题之句元题曰日光照吾民月色清我心又题琴曰至治之音二首 其二","f":"五言律诗","c":["御翰龙池晓，翻经鹫殿阴。","云依清静叶，月印妙明心。","千载堂堂去，诸天肃肃临。","朱弦谁为鼓？","至治有遗音。"]},{"t":"正月十一日朝回即事","f":"五言古诗","c":["宫树春阴合，霓旌拂曙来。","天光临阁道，云气转蓬莱。","昼漏沈沈鼓，晨尊滟滟杯。","香霏帘底雾，乐殷殿前雷。","祥瑞仪曹奏，珍淳尚食催。","舞庭分鹭序，效献过龙媒。","融雪微生草，轻风不动埃。","老人南极至，王母上方回。","玉色何多喜，金华得重陪。","裁诗贺新雨，西阁待门开。"]},{"t":"赠别兵部崔郎中暂还高丽即回中朝","f":"五言古诗","c":["束发来东海，从军护北门。","珠光连旭景，玉气达春温。","渊静龙含德，门严虎列屯。","从容参幄帐，慷慨属櫜鞬。","拜表推黎献，趋朝谒至尊。","云依温室树，星入紫微垣。","不道璠玙贵，仍婴管库烦。","利行虽近市，义守不窥园。","眷遇忘身得，危难欲手援。","怀邦维父母，于国实甥婚。","□□还羁靮，原原致璧飧。","鲁连名竟重，箕子教应存。","简在从当日，扶持□宿藩。","清宫风肃肃，骖乘火焞焞。","帝所为郎重，王家报礼惇。","暂伸桑梓敬，未爱李桃繁。","神阙秋期早，康侯昼锡蕃。","九成思阁凤，六月待冥鹍。"]},{"t":"次韵李侍读东平王哀诗","f":"五言古诗","c":["宇宙生奇变，明良陷逆图。","传闻昏白昼，悲愤结全区。","治极机潜否，恩深事失谟。","犯车仍断軏，坏户竟伤枢。","魑魅嫌明镜，强梁忌雅模。","甘心成首祸，藉口肆群腴。","隐忍危冲决，凭陵善唯俞。","自天傒鈇钺，累月具箪壶。","裹革疑亡地，招魂竞出都。","笳鸣残夕月，马偾四交衢。","所痛仓皇际，将无古昔殊。","腹心何蛊蚀，肘腋不支梧。","列位多翘楚，干城总豹貙。","讵言归厄数，不复颂贞符。","天讨公无赦，皇心爱不姑。","报雠论婉娈，锡爵酹呜呼。","相业今如在，民生实少痡。","谁能疵璧玉，唯有泣琼珠。","执简书群盗，当关欠一夫。","驰奔嗟薄日，沐浴止中途。","决去思投阙，违之或汎湖。","危知无复死，恨不奋前诛。","春雨烦冤涤，朝阳癙思疏。","讴吟申感慨，述作惧荒芜。","芒忽思离散，焄蒿起苑枯。","神还嵩岳峻，气直斗杓孤。","陟降先皇侧，回翔造化徒。","英灵常会合，瞻想岂虚无。"]},{"t":"送陈硕","f":"五言古诗","c":["六岁过闽郡，书声忆满城。","目盲今子夏，心醉昔延平。","尔叔同游息，吾文愧老成。","每分重席煖，相对一灯明。","远海乘桴意，高山伐木情。","愿携邛竹杖，往看离支生。","辟掾青衫旧，趋庭綵服轻。","为言穿木榻，亦未厌藜羹。","宝瑟留飞雁，兰舟及啭莺。","佩怀湘渚赠，绶向会稽迎。","去去江云湿，飘飘鸟雾清。","重来知有意，时我已归耕。"]},{"t":"奎章阁有灵壁石奇绝名世御书其上曰奎章玄玉有敕命臣集赋诗臣再拜稽首而献诗曰","f":"五言古诗","c":["《禹贡》收浮磬，尧阶望矞云。","自天承雨露，拔地起絪缊。","击拊磬音合，衡从玉兆分。","巨鳌三岛力，威凤九苞文。","辨位资乾坎，为山填幅员。","固知兴宝藏，不假运神斤。","书帙侵春润，香炉借宿薰。","烟光晴冉冉，波影昼沄沄。","融结由元化，登崇荷圣君。","瑞于龟出洛，重若鼎来汾。","柱立尊皇极，磐安广帝勋。","讵云陈秘玩，因愿献前闻。"]},{"t":"赠星上人归湘中","f":"七言律诗","c":["潭北湘南无影树，一花吹度海门潮。","天香满室定初起，云气上衣身欲飘。","宝月夜寒龙在钵，银河秋近鹊成桥。","岂无一个邛州竹，与尔松根共寂寥。"]},{"t":"谢茅山主者赠白罗氅衣请为作大洞祖宗师四十五赞","f":"七言律诗","c":["鹤氅裁成雪色新，仙翁持寄感情真。","清高自此全抛俗，宽博由来稳称身。","佩玉洞闻云外响，剑光飞射日中尘。","画图写向群真里，便是挥豪赞咏人。"]},{"t":"送莫京甫广宪经历","f":"七言律诗","c":["延春阁下承恩日，是我经帷侍讲时。","方拥青编临绮席，遥看朱绂拜丹墀。","风微细草鸣珂佩，日煖飞花近鬓丝。","上忆远人常轸念，莫言南海是天涯。"]},{"t":"欧阳元功待制入院后仆以兼领成均辰酉甚严绝不得相见今夜当同宿斋宫赋此先寄并简谢敬德修撰","f":"七言律诗","c":["学省初兼禁直稀，故人同署却相违。","食馀苜蓿承朝日，坐候棠梨过夕晖。","预喜奉祠秋寺烛，定知催襆早朝衣。","今晨瘦马经门巷，想拥青绫尚掩扉。"]},{"t":"次韵张蔡国公淡庵青山寺诗","f":"七言律诗","c":["相国观山负夙期，圣恩祇许暂相违。","身随云影留三宿，心了泉声绝百非。","开士谈空依宝树，野人耕雨荐山薇。","双龙深护安禅处，绕坐诸天近紫微。"]},{"t":"次韵国子监同官二首 其一","f":"七言律诗","c":["坐隐乌皮髀肉消，诸生应笑懒边韶。","阶前老马随秋草，袖里遗编俟早朝。","乞米西邻晨有粥，留家南国暑无绡。","经明亦是归耕好，清梦无时万里桥。"]},{"t":"次韵国子监同官二首 其二","f":"七言律诗","c":["学宫南直禁垣阴，假寓惟愁两壁沈。","一曲镜湖遗老事，三年经幄小臣心。","银河回夜天逾近，草径迎秋露转深。","珍重乡人居巷北，时能来往和鸣琴。"]},{"t":"次韵马伯庸宝监学士见贻诗并简曹子贞学士燕信臣待制彭允蹈待制","f":"七言律诗","c":["禁庐晓直夹城西，经笥龙光映壁奎。","绕阁浮云飞野马，当阶生草伏驯麛。","雷行已识天无妄，风烈唯闻帝弗迷。","徒积寸诚无补报，每还冰署欲鸡栖。"]},{"t":"鳌峰者国史院庭中石名也伯宁御史为仆言自其先公时与诸老名胜赋诗者盖数百篇今玉堂无本而御史家具有之且曰峰所托差低盍稍崇其址乃八月五日既克如命因赋此以报且请录示旧诗补故事以传云","f":"七言律诗","c":["视草堂前石一拳，何人移置自何年？","久怜翠色连重地，故拔孤根近九天。","俯仰百年承雨露，等閒千尺接云烟。","故家御史遗书在，为录鳌峰旧赋篇。"]},{"t":"题南野亭","f":"七言律诗","c":["门外烟尘接帝扃，坐中春色自幽亭。","云横北极知天近，日转东华觉地灵。","前涧鱼游留客钓，上林莺啭把杯听。","莫嗟韦曲花无赖，留擅终南雨后青。"]},{"t":"次韵伯庸尚书春暮游七祖真人庵兼简吴宗师二首 其一","f":"七言律诗","c":["石渠承雨作流泉，中有参差荇菜牵。","花近飞觞鱼骇逝，柳低步障燕随穿。","红尘朝路常参吏，清昼斋居几劫仙。","但乞会稽寻贺监，酒船一棹水中天。"]},{"t":"次韵伯庸尚书春暮游七祖真人庵兼简吴宗师二首 其二","f":"七言律诗","c":["一住京华三十年，春花秋月谩相牵。","高情总付珠帘卷，危坐空馀木榻穿。","水曲停骖新禊事，墙阴题字昔游仙。","动成陈迹多惆怅，安得长生老后天。"]},{"t":"触石坠马卧病蒙恩予告先至上京寄溉之学士敬仲参书二首 其一","f":"七言律诗","c":["翠幄临都尚驻郊，言瞻龙漠度前茅。","雨馀草气千原合，日下云章五色交。","给札修辞持玉笔，赐羹充腹出珍庖。","白头感遇知何补，阿阁清严栖凤巢。"]},{"t":"触石坠马卧病蒙恩予告先至上京寄溉之学士敬仲参书二首 其二","f":"七言律诗","c":["趋召颠隮叹目昏，旋闻予告荷深恩。","药颁西域千金剂，酒赐初筵九酝尊。","默忆旧书忘昼永，行吟冷署觉春温。","摩挲素壁光于雪，思得参书写树根。"]},{"t":"云州道中数闻异香","f":"七言律诗","c":["云中楼观翠岧峣，载道飞香远见招。","非有芝兰从地出，略无烟雾只风飘。","玉皇案侧当霄立，王母池边向日朝。","却袖馀薰散人世，九天清露海尘飘。"]},{"t":"次韵杨友直北行道中","f":"七言律诗","c":["萧萧戎马昔升虚，壮士吹笳惨不舒。","关外羽书三月急，道傍茅舍百年馀。","沙田雨足仍生黍，河水冰消不禁渔。","洛下贾生犹献策，平明立在玉阶除。"]},{"t":"王仪伯参政见和郊字韵诗复用韵叙谢二首 其一","f":"七言律诗","c":["龙游宫沼凤游郊，通水明堂不剪茅。","绵蕝草仪三日具，大亨飨帝五云交。","执舆已信神为马，和鼎宁容祝代庖。","八月凉风张乐地，颂声洋溢播云巢。"]},{"t":"王仪伯参政见和郊字韵诗复用韵叙谢二首 其二","f":"七言律诗","c":["圣远言湮感垫昏，河汾千载最知恩。","垂绅论道称前古，束发明经奉至尊。","车骑身从游汗漫，庭闱心在视寒温。","朝回未觉归途晚，斗柄西移揭角根。"]},{"t":"次韵马伯庸尚书","f":"七言律诗","c":["邃阁晨趋禁掖西，暮街骑马及鸡栖。","退朝每想花边散，得句应从竹上题。","赐被南宫无宿火，斋居方丈有蒸藜。","凤池何似承明近，久候文星共聚奎。"]},{"t":"二十五日即事呈阁老诸学士","f":"七言律诗","c":["松阴鹄立候宫车，风送飞花著白须。","水影渐移帘侧畔，莺声祗在殿东隅。","近床儗进名臣操，载笔亲题列女图。","太液雨馀波浪动，龙舟初试散鱼凫。"]},{"t":"赋砀山成简卿心远亭","f":"七言律诗","c":["作亭临河河水浑，草树绕屋啼鸟闻。","梦回枕上彭城雨，目送檐间芒砀云。","归来黄菊有佳色，坐老青山无垢氛。","但愿尊中长得酒，曲阿莫问旧参军。"]},{"t":"谢吴宗师送牡丹并简伯庸尚书","f":"七言律诗","c":["轻风紫陌少尘沙，忽见金盘送好花。","云气自随仙掌动，天香不许世人夸。","青春有态当窗近，白发多情插帽斜。","最爱尚书才思别，解吟胡蝶出东家。"]},{"t":"送进士刘闻文廷赴临江录事","f":"七言律诗","c":["清江百尺石为城，太华千峰积雨晴。","官府几时书帙静，渔舟尽日钓丝轻。","故家好访春秋学，上国多传月旦评。","颇有老怀烦录事，到州为问范先生。"]},{"t":"大廷策士问经世之道仆忝在读卷之列观诸进士所对有感赋此录以赠别刘性粹中支渭兴文举二贤良","f":"七言律诗","c":["昔人有欲问先天，林下相期二十年。","已向尘埃成白发，尚从灯火事青编。","获麟遂讫春秋后，鸣鸟犹闻礼乐前。","春雨未来农事晚，独怀归计在山田。"]},{"t":"罗朋友道擢高科拜官还崇仁赋此为别","f":"七言律诗","c":["重溪叠嶂竹交加，曾著芒鞋踏白沙。","名胜多年嗟寂寞，文章此日羡才华。","青云步武才重见，白屋诗书尚几家。","乡邑相逢烦告语，好敦忠信作生涯。"]},{"t":"赠赵生","f":"七言律诗","c":["天门一日观黄榜，茅屋三年掩素扉。","湘帙蠹鱼春雨润，綀囊萤火夜光微。","梦游朔雪留鸿迹，思入南山望鹤飞。","会倚宫墙看射策，上林初日炫朝衣。"]},{"t":"访李真人不遇","f":"七言律诗","c":["退朝花底佩珊珊，去访真人晓出关。","芳草欲迷行径古，长松深护步廊閒。","苍龙挟雨得瑶简，白鹿穿云致玉环。","如到天坛看月影，定知清露满人间。"]},{"t":"赋壶洲","f":"七言律诗","c":["传闻海上有玄洲，曾是安期旧所游。","千顷白云都种玉，一杯弱水不胜舟。","鱼龙夜护黄金鼎，鸾鹄晨朝紫绮裘。","波浪不惊星斗近，步虚声里度清秋。"]},{"t":"次韵朱本初访李溉之学士不遇","f":"七言律诗","c":["城南城北煖尘飞，伐木相求苦未归。","吟到碧桃还细雨，行寻芳草又斜晖。","绮窗綵笔题诗遍，斗帐沈香入袖微。","共载小车胜上马，重游莫待晓红稀。"]},{"t":"寄赵子敬平章","f":"七言律诗","c":["闻道乘閒入翠微，犹愁岚气湿人衣。","道旁野树飞花尽，溪上春云作雨归。","故旧钓丝轻在手，仙人棋局静忘机。","赤松曾许同千载，儗向高秋傍鹤飞。"]},{"t":"仁寿寺僧报更生佛祠前生瑞竹有怀故园三首 其一","f":"七言律诗","c":["闻道故园生瑞竹，试从来使问何如？","苍筤独出千丛里，翠节骈生数尺馀。","比管可吹丹穴凤，长竿莫钓锦溪鱼。","折筳已向灵氛卜，亦说能归似两疏。"]},{"t":"仁寿寺僧报更生佛祠前生瑞竹有怀故园三首 其二","f":"七言律诗","c":["闻道故园生瑞竹，令人归兴满江干。","扁舟不畏瞿塘险，匹马谁云蜀道难。","杜甫溪头花匼匝，孔明庙里柏阑珊。","新堂题作归欤字，定得临江把钓竿。"]},{"t":"仁寿寺僧报更生佛祠前生瑞竹有怀故园三首 其三","f":"七言律诗","c":["闻道故园生瑞竹，吾家孙子好归看。","佛祠竟日春阴覆，先陇多年暮雨寒。","门户凄凉嗟老病，乡关迢递报平安。","重来慎勿劳余梦，驷马桥边据马鞍。"]},{"t":"别国史院鳌峰石","f":"七言律诗","c":["执戟扬郎久不迁，频年从幸到甘泉。","赐归特许先三日，作赋时令奏一篇。","翠勺娱人花带露，貂裘倚马草横烟。","殷勤为谢堂前石，何处来秋共月圆。"]},{"t":"谢书巢惠梅花","f":"七言律诗","c":["巢翁远送梅花树，正在东风四日前。","红萼无言馀旧雪，白头相见又新年。","喜从嘉树来江雨，忆共香粳上海船。","春夜不眠宾客醉，只留孤鹤伴清妍。"]},{"t":"再用韵简巢翁","f":"七言律诗","c":["岂无尊酒梅花侧，闻道长斋绣佛前。","方阁护云宜煖日，小车冲雪称高年。","颇辞阁下金莲炬，但乞湖中罨画船。","约取巢翁携鹤去，鬓毛同白不争妍。"]},{"t":"送王君实御史","f":"七言律诗","c":["顿觉文星阙下稀，旁人犹道此言非。","东风十日京城雪，西道三春客子衣。","莺满辋川君定到，鹃啼剑阁我思归。","千花并绕图书府，相待承恩入紫微。"]},{"t":"送欧阳元功谒告还浏阳","f":"七言律诗","c":["晓奉新书进御床，解缨随见濯沧浪。","归鸿不计江云阔，倦骥空怀野水长。","竹簟暑风魂梦远，茶烟清昼鬓毛苍。","篮舆千里宜春道，投老相求访石霜。"]},{"t":"八月十五日伤感","f":"七言律诗","c":["宫车晓送出神州，点点霜华入敝裘。","无复文章通紫禁，空馀涕泪洒清秋。","苑中苜蓿烟光合，塞外蒲萄露气浮。","最忆御前催草诏，承恩回首几星周。"]},{"t":"送许有孚赴湖广提举","f":"七言律诗","c":["奉诏抡文秘殿西，才华知合籍金闺。","思亲浩荡江波远，恋阙迟回苑树低。","望鹤楼前移綵鹢，吟诗花底听黄鹂。","归来尚觉春风早，雁字充庭玉笋齐。"]},{"t":"赋石竹","f":"七言律诗","c":["积雪初消萼绿华，东风吹动绛绡霞。","龙嘘石气千年润，鹤过林阴一径斜。","刻字欲寻金错落，析旌如织翠交加。","绮窗坐对吹笙煖，未觉人间岁月赊。"]},{"t":"奉同吴宗师赋蔡七祖新斋","f":"七言律诗","c":["城南烟树听莺啼，石上莓苔觅旧题。","自有琴心传内景，更将书帙事幽栖。","晚来相鹤风生竹，雨过笼鹅水满溪。","蜀客草玄成底事，萧条白发愧青藜。"]},{"t":"寄来鹤亭主人","f":"七言律诗","c":["德清旧馆何时到，雨后春泉定满池。","绿字久无弘景信，紫苔应长少霞碑。","数峰烟树天垂野，千顷鸥波雨散丝。","海内交游多老去，为谁溪上放船迟。"]},{"t":"送张兵部巡视运河","f":"七言律诗","c":["画桥冰泮动龙舟，鸭绿粼粼出御沟。","使者旌旗穿柳过，人家凫雁傍溪浮。","桃花吹雨春牵缆，江水平堤夜唱筹。","应有馀波方浩荡，不令归楫恨淹留。"]},{"t":"谢吴宗师惠墨","f":"七言律诗","c":["念我衰年不废书，锦囊古墨送幽居。","明窗尘影丹同熟，玄圃云英玉不如。","敢为文章胜虎豹，祗应笺注到虫鱼。","研磨不尽人间老，传与儿孙尚有馀。"]},{"t":"三用韵答巢翁就以奎章赐墨赠之","f":"七言律诗","c":["邻父长思长史书，不辞频谒恼巢居。","临池三月玄霜尽，对月千篇白雪如。","赋敌洛波翔翠羽，歌成湘浦媵文鱼。","故分泸石松烟色，犹是奎章旧赐馀。"]},{"t":"题著色山图","f":"七言律诗","c":["江树重重江水深，楚王宫殿在山阴。","白云窈窕生春浦，翠黛婵娟对晚岑。","宋玉少时多讽咏，江淹老去倦登临。","扁舟却上巴陵去，閒听孤猿月下吟。"]},{"t":"题画","f":"七言律诗","c":["缉熙殿里御屏风，零落谁收百岁中。","锦树总含春雨露，画桥犹是旧青红。","花开陌上怀归燕，潮落江头送去鸿。","何似绿波生太液，绛桃风急綵船东。"]},{"t":"寄海南故将军","f":"七言律诗","c":["海上风来五月秋，晚凉应上木兰舟。","金盘丹荔生南国，玉椀清冰出北州。","狂客醉时花作阵，美人歌罢月如钩。","期门旧识将军面，从猎还披翠羽裘。"]},{"t":"次韵宋诚甫学士城南访病暮归","f":"七言律诗","c":["骑马城南觅旧题，飘萧席帽碧云低。","东风花柳过韦曲，落日儿童唱大堤。","绣阁岂无和玉髓，锦囊还有铸金蹄。","归来吟转楼头月，池冷芙蓉翡翠栖。"]},{"t":"题康里子山尚书凝春小隐六韵","f":"七言古诗","c":["群玉府中香满袖，凝春亭里看花开。","綵云近席微风动，红日当窗好客来。","西海珊瑚阶下长，东家胡蝶雪中回。","竹深每听尚书履，池暖时分太液杯。","凤咮浮烟金错落，鹅群随水白毰毸。","人间应得函封帖，青李来禽绕舍栽。"]},{"t":"次韵杜德常博士万岁山","f":"七言古诗","c":["秘阁沈沈便殿西，频年立此听春鹂。","风摇翠岸新生柳，雨浥铜池旧产芝。","玉几由来常咫尺，衡门此日遂栖迟。","申生欲去柴车在，杜甫长吟雪鬓垂。","墨沼游鱼翻宿藻，画檐飞燕罥晴丝。","山中竹簟凉如水，应共钧天九奏时。"]},{"t":"次韵宋显甫","f":"七言古诗","c":["御沟雪融三月初，凫鹥鸿雁总来居。","蒲萄水绿可为酒，杨柳条青堪贯鱼。","迤逦天河起箕尾，滉瀁云海浮青涂。","舟前花落傍飞燕，堤上风来湿舞裾。","翠辇时留金騕袅，锦波不著玉芙蕖。","临流宋玉偏能赋，莫待东都客问予。"]},{"t":"燕陈公子宅赠燕学士","f":"五言绝句","c":["落日照大堤，花间闻马嘶。","城头鼓角起，相送五门西。"]},{"t":"宣和墨竹寒雀","f":"五言绝句","c":["洒墨写琅玕，深宫春昼閒。","萧条数枝雪，不似纥干山。"]},{"t":"上马","f":"五言绝句","c":["眼昏身手钝，上马怕风沙。","祇好扶藜杖，循篱看落花。"]},{"t":"画双蝶","f":"五言绝句","c":["舞罢庭花落，池边看睡凫。","无端双蛱蝶，飞上绣罗襦。"]},{"t":"捕鱼图","f":"五言绝句","c":["网罟日相从，天寒泽国空。","钓竿长倚树，老却渭川翁。"]},{"t":"题柯敬仲杂画十首 其一","f":"五言绝句","c":["北苑今仍在，南宫奈老何。","青山解浮动，端为白云多。"]},{"t":"题柯敬仲杂画十首 其二","f":"五言绝句","c":["雨过苍苔石，云生野岸泉。","幽怀春冉冉，稚子秀娟娟。"]},{"t":"题柯敬仲杂画十首 其三","f":"五言绝句","c":["铁石馀生色，冰霜作晓妍。","春雷明日起，何处尚龙眠。"]},{"t":"题柯敬仲杂画十首 其四","f":"五言绝句","c":["昔过筼筜谷，钩衣石角斜。","儗寻龙作杖，拾得上天槎。"]},{"t":"题柯敬仲杂画十首 其五","f":"五言绝句","c":["黄金千琐甲，雕玉六帘钩。","雨送鸳鸯梦，烟笼翡翠愁。"]},{"t":"题柯敬仲杂画十首 其六","f":"五言绝句","c":["娟娟生玉润，楚楚作金声。","羽扇迎风定，羊车过月明。"]},{"t":"题柯敬仲杂画十首 其七","f":"五言绝句","c":["峡口春云重，江南夜雨多。","水深桃叶渡，风急《竹枝歌》。"]},{"t":"题柯敬仲杂画十首 其八","f":"五言绝句","c":["平陆苍龙起，近山生远烟。","前村三万顷，明日水平田。"]},{"t":"题柯敬仲杂画十首 其九","f":"五言绝句","c":["莓苔生石路，翠竹自交加。","不惜青鞋湿，临流踏白沙。"]},{"t":"题柯敬仲杂画十首 其十","f":"五言绝句","c":["昨夜采樵去，偶逢三尺枯。","山人不到海，不识是珊瑚。"]},{"t":"题李溉之学士湖上诸亭 其一 烟萝境","f":"五言绝句","c":["玉女乘烟雾，松间采薜萝。","飞行了无迹，明月送空歌。"]},{"t":"题李溉之学士湖上诸亭 其二 金潭云日","f":"五言绝句","c":["金沙滩上日，潭底见行云。","祇有琴高鲤，时时或作群。"]},{"t":"题李溉之学士湖上诸亭 其三 漏舟","f":"五言绝句","c":["春水如天上，秋潭见月中。","如何列禦寇，犹欲待泠风。"]},{"t":"题李溉之学士湖上诸亭 其四 秋水观","f":"五言绝句","c":["湖深山影碧，天净月光空。","幸自无波浪，蘋花谩晚风。"]},{"t":"题李溉之学士湖上诸亭 其五 无倪舟","f":"五言绝句","c":["三周华不注，水影浸青天。","不上银河去，空明击棹还。"]},{"t":"次韵竹枝歌答袁伯长三首 其一","f":"七言绝句","c":["沙禽东去避网罗，荡舟相逐如远何。","越山青青越女白，从此劳人魂梦多。"]},{"t":"次韵竹枝歌答袁伯长三首 其二","f":"七言绝句","c":["春江风涛苦欲归，东尽沧溟南斗低。","明年白日百花静，忆尔琴中乌夜啼。"]},{"t":"次韵竹枝歌答袁伯长三首 其三","f":"七言绝句","c":["燕姬当炉玉雪清，箫中吹得凤凰声。","不及晴江转柁鼓，洗盏船头沙鸟鸣。"]},{"t":"木芙蓉","f":"七言绝句","c":["九月襄王宴渚宫，霓旌翠羽度云中。","满汀山雨衣裳湿，宋玉愁多赋未工。"]},{"t":"水芙蓉","f":"七言绝句","c":["长洲宫沼醉西施，荡漾兰舟不自持。","愿奉君王千岁乐，一盘清露玉淋漓。"]},{"t":"送四川宪使","f":"七言绝句","c":["已叹玄经返墨池，复愁国史奉严祠。","离乡游子归仍晚，独对东风惜鬓丝。"]},{"t":"曹将军马","f":"七言绝句","c":["高秋风起玉关西，踣铁归朝十万蹄。","貌得当时第一匹，昭陵风雨夜闻嘶。"]},{"t":"马图","f":"七言绝句","c":["昔在乾淳抚蜀师，卖茶买马济时危。","乡人啜茗同观画，解说前朝复有谁。"]},{"t":"王母图 其一","f":"七言绝句","c":["偷桃小儿痴且妍，恃恩无赖更蒙怜。","窃翻雷电天公怒，风雨落花红九川。"]},{"t":"王母图 其二","f":"七言绝句","c":["黄竹遗墟白雪高，空桑戴胜向晨嗥。","茂陵多欲非仙器，枉赐金盘五色桃。"]},{"t":"竹杏沙头鸂鷘","f":"七言绝句","c":["蛱蝶飞来石竹丛，罗襦曾试绣纹重。","荷花啼鸟银屏煖，卧看窗间唾碧茸。"]},{"t":"记梦中诗三首 其一","f":"七言绝句","c":["出海云霞九色芒，金容滉瀁水中央。","向曾赐服玄洲玉，今结萧台五凤章。"]},{"t":"记梦中诗三首 其二","f":"七言绝句","c":["飞步崔嵬上九宫，亲题綵笔篆明虹。","玉楼临海连天碧，待子扶桑鹤出笼。"]},{"t":"记梦中诗三首 其三","f":"七言绝句","c":["失脚渔矶返棹迟，几回石上候来期。","老翁岩下诸年少，总解题诗笑鬓丝。"]},{"t":"钱舜举折枝芙蓉","f":"七言绝句","c":["白发多情忆剑南，秋风溪上看春酣。","剪来一尺吴江水，儗比千花濯锦潭。"]},{"t":"赋故宋李文襄公植乌石渡旧隐","f":"七言绝句","c":["窈窕幽篁带薜萝，青春白日坐蹉跎。","试询乌石江头水，宁有微波接汨罗。"]},{"t":"访杜弘道长史不值道中偶成","f":"七言绝句","c":["雨浥轻尘道半乾，朝回随处借花看。","墙东千树垂杨柳，飞絮时来近马鞍。"]},{"t":"听雨","f":"七言绝句","c":["屏风围坐鬓毵毵，绛蜡摇光照暮酣。","京国多年情尽改，忽听春雨忆江南。"]},{"t":"春云","f":"七言绝句","c":["春云漠漠度宫城，楼雪初融水未生。","行过御沟成久立，起头枝上有流莺。"]},{"t":"与赵子期趋阁","f":"七言绝句","c":["日出风生太液波，画桥千尺彩船过。","桥头柳色深如许，应是偏承雨露多。"]},{"t":"玉堂读卷杂赋次韵 其一","f":"七言绝句","c":["待漏宫门听钥开，袖中进卷总贤才。","奏名殿里千花合，传敕阶前好雨来。"]},{"t":"玉堂读卷杂赋次韵 其二","f":"七言绝句","c":["千花覆槛柳垂丝，昼刻传呼淑景迟。","圣主自观新进策，侍臣簪笔立多时。"]},{"t":"院中独坐","f":"七言绝句","c":["何处他年寄此生，山中江上总关情。","无端绕屋长松树，尽把风声作雨声。"]},{"t":"题欧阳原功少监家柯敬仲画","f":"七言绝句","c":["涔阳日日水生波，翠袖黄裳晚棹过。","珠树月明花婀娜，凤毛春煖锦婆娑。"]},{"t":"绍兴间临安士人有赋曲一春长费买花钱日日醉湖边玉骢惯识西湖路骄嘶过沽酒楼前红杏香中箫鼓绿杨影里鞦韆晚风十里丽人天花压鬓云偏画船载得春归去馀情付湖水湖烟明日重扶残醉来寻陌上花钿思陵见而喜之恨其后叠第五句重携残酒酸寒改曰重扶残醉因欧阳原功言及此与陈众仲寻腔度之歌之一再董此宇求书其事因书之并系以此诗","f":"七言绝句","c":["重扶残醉西湖上，不见春风见画船。","头白故人无在者，断堤杨柳舞青烟。"]},{"t":"八月十五日得旨先归驿骑在门复召还草诏十七日至桓州驿题壁","f":"七言绝句","c":["乌桓东望天无际，祗有银蟾出海头。","不得吹箫送清夜，禁城钟鼓度中秋。"]},{"t":"酬书巢送棕帚","f":"七言绝句","c":["积雨苍苔路不分，松花尽日落纷纷。","尘埃满袖归来晚，谁与柴门扫白云。"]},{"t":"子昂画","f":"七言绝句","c":["棠梨枝上白头翁，墨色如新最恼公。","直似故园花石外，铜盘和露写东风。"]},{"t":"画马二首 其一","f":"七言绝句","c":["萧条沙苑贰师还，苜蓿秋风尽日閒。","白发圉人曾习御，长鸣知是忆关山。"]},{"t":"画马二首 其二","f":"七言绝句","c":["虢国夫人学画眉，宫门催入许先驰。","春风十里闻芗泽，新赐金鞍不受骑。"]},{"t":"题纳凉图","f":"七言绝句","c":["百顷芙蓉水满堤，绮窗只在画桥西。","羊车薄暮过湖曲，惊起鸳鸯不并栖。"]},{"t":"息斋竹","f":"七言绝句","c":["紫貂早解猎围骖，一棹夷犹雪满簪。","山雨欲来春树暗，尽将情思写江南。"]},{"t":"题子昂春江听雨图","f":"七言绝句","c":["忆昔江湖听雨眠，翩翩归雁度春前。","数株古木依茅舍，老去何年踏钓船。"]},{"t":"次韵杜德常典签秋日西山有感二首 其一","f":"七言绝句","c":["落日龙舟山下回，寺门依旧对山开。","霜凋碧树烟生草，从此频伤八月来。"]},{"t":"次韵杜德常典签秋日西山有感二首 其二","f":"七言绝句","c":["每进文章出殿迟，日华西转万年枝。","甘泉罢幸扬雄老，满鬓秋风不受吹。"]},{"t":"题柯敬仲画","f":"七言绝句","c":["牵牛引蔓上棠梨，上有幽禽夜夜栖。","自有秋风动疏竹，江南落月不须啼。"]},{"t":"题蔡端明苏东坡墨迹后四首 其一","f":"七言绝句","c":["祗今谁是钱塘守，颇解湖中宿画船。","晓起斗茶龙井上，花开陌上载婵娟。"]},{"t":"题蔡端明苏东坡墨迹后四首 其二","f":"七言绝句","c":["老却眉山长帽翁，茶烟轻飏鬓丝风。","锦囊旧赐龙团在，谁为分泉落月中。"]},{"t":"题蔡端明苏东坡墨迹后四首 其三","f":"七言绝句","c":["三生石上旧精魂，邂逅相逢莫重论。","纵有绣囊留别恨，已无明镜著啼痕。"]},{"t":"题蔡端明苏东坡墨迹后四首 其四","f":"七言绝句","c":["能言学得妙莲华，赢得春风对客誇。","乞食衲衣浑未老，为题灵塔向金沙。"]},{"t":"题著色山图","f":"七言绝句","c":["巫山空翠湿人衣，玉笛凌虚韵转微。","宋玉多情今老矣，閒云閒雨是耶非。"]},{"t":"题东坡帖","f":"七言绝句","c":["鱼复浦前春水生，负薪渡江初月明。","凭郎莫下巫峡去，楚王宫殿在专城。"]},{"t":"腊日偶题","f":"七言绝句","c":["旧时燕子尾毵毵，重觅新巢冷未堪。","为报道人归去也，杏花春雨在江南。"]},{"t":"题扇与周干臣","f":"七言绝句","c":["玉叠松花蜜饼香，龙珠星颗露盘凉。","遥知环碧楼中坐，翠竹苍松夏日长。"]},{"t":"题周怡临韩干明皇出游图","f":"七言律诗","c":["开元盛事何人画，玉冠芙蓉御天马。","从官骑步各有持，移仗华清意閒暇。","宫袍如锦照青春，诏许传看思古人。","不知身在瀛洲上，亲奉图书侍紫宸。"]},{"t":"徽宗画梨花青禽图","f":"七言绝句","c":["宿雨初收禁林寂，玉斧临窗看春色。","蒺藜沙上煖尘飞，何处人间作寒食。"]},{"t":"赵千里小景","f":"七言绝句","c":["前代王孙不好武，拈笔幽窗写汀渚。","残云野水三百年，依旧松筠湿春雨。"]},{"t":"韩干马","f":"七言绝句","c":["开元沙苑蒺藜秋，韩干新图总不收。","天厩真龙奇骨在，故知臣甫负骅骝。"]},{"t":"曹霸下槽马","f":"七言绝句","c":["枥下长年饱豆刍，谁通马语识踟蹰？","主恩深重知何报，或者东封驾鼓车。"]},{"t":"滕昌祐蘹香睡鹅图","f":"五言律诗","c":["苍鹅惜毛羽，宛宛卧春雨。","雨馀日照沙，上有蘹香花。","怀香不自献，梦到金鸾殿。","殿池多跃鱼，君王方草书。"]},{"t":"竹林七贤图","f":"曲","c":["瞻彼修竹，下临清流。","文石偃堤，华松荫丘。","植表界壤，剪茅宅幽。","梁度高巘，台隐中洲。","方床读书，异宫同休。","咏歌相闻，觞豆相求。","或莳名药，或钓游鯈。","课艺嘉植，坐思远游。","濯缨微波，看云良畴。","逸而不放，俨而自修。","泰哉沮溺，邈乎巢由。","按图以观，永宜春秋。","孰若五君，遗其故俦。","糟粕尘世，高踪庄周。","我怀古人，遁而违忧。","安得挥弦，以招沈浮。"]},{"t":"题汪华玉所藏兰亭图","f":"五言古诗","c":["衡茅负晴旭，有客至我门。","共披会稽图，山水盛缤纷。","众贤坐水次，飞觞汎沄沄。","夷旷各有趣，高閒知右军。","幽情付后览，陈迹感前欣。","悠悠千载来，不异更旦昏。","探穴问神禹，望海悲秦君。","逝者皆如斯，死生固奚云。","所以鼓瑟人，思从童冠群。","春服沂新浴，归欤聊永言。","抚卷不知老，遐思在兹文。","东南极积水，日暮多浮云。"]},{"t":"玉隆留题","f":"五言古诗","c":["仙真治兹山，重阜隐延广。","冲奥元气会，运至法灵响。","与世作司命，神宇廓弘敞。","及门春雨来，玄感副夙仰。","摩挲晋时树，托身何萧爽。","千载抱微息，日月共来往。","欲为黄发期，日待紫芝长。","上天垂光彩，月出江海上。","故人不可待，惆怅理归鞅。"]},{"t":"记梦","f":"五言古诗","c":["梦行衡庐间，千仞过苍壁。","崇高仰神明，深广下不测。","云雨蓄盘礴，时至如欲出。","絪缊尚回旋，挥霍忽奔逸。","物怪匿岩穴，愯若俟霹雳。","黑波汎高树，木叶走崩石。","升身登玄间，纵观龙变迹。","俯视九州野，草木有辉泽。","乃在风雨外，手画素三尺。","挥豪极动荡，落墨更沈郁。","图成示坐人，共笑不可得。","顾瞻以踟蹰，恍惚增叹息。","因之命肩舆，出门聊有适。","大术何舒舒，白鹤从数客。","略经幽涧滨，便上青松侧。","凭高望远水，双景荡虚碧。","拂石共客坐，芳草藉尻膝。","忽然闻钟声，睡觉北窗席。"]},{"t":"次韵陈溪山棕履二首 其一","f":"五言古诗","c":["解舄还上方，归山据枯槁。","禁足结僧夏，陈编谢探讨。","隐几或过昼，凝尘遂忘扫。","行庭不见人，谁或践生草。","实由筋力衰，无复驰走好。","前年当此时，严召出城早。","追度龙门水，赐见沙领道。","鼎湖忽踰年，始克罢趋造。","感君素履咏，幽贞可长保。","番番茹芝人，长歌岂知老。"]},{"t":"次韵陈溪山棕履二首 其二","f":"五言古诗","c":["六月乃屡雨，良田不忧槁。","独念桂林戍，触热赴南讨。","道路备攘掠，所过净于扫。","缚人夜送军，吏卒何草草。","蛮獠亦人类，义利启戎好。","寻原可制乱，机要贵及早。","夜来送者还，颇言暍横道。","诸军四面集，同月约皆造。","谁为饥渴谋，性命安可保。","藜藿虽满盘，对之令人老。"]},{"t":"和陈溪山韵","f":"五言古诗","c":["幽人慎素履，古道思独往。","瞋目登高台，浮云不足上。","丹砂炼仙骨，沆瀣濯神爽。","远怀澄江静，耿若孤月朗。","河汉自倾注，山川邈游想。","敛迹倦飞翼，归耕故时壤。","好风从东来，空谷感遗响。","诏书荐遗逸，郡府属高仰。","聊持东湖水，往助敬亭赏。"]},{"t":"楚石琛藏主自蒋山归却欲就丛林阅藏同舟清江之上赋此赠之","f":"五言古诗","c":["手携北山云，却上西江水。","月明洲渚生，叶落风不起。","虚舟不移棹，寒波钓金鲤。","银河转碧落，北斗去天咫。","龙吟匣中剑，虎跃弦上矢。","杀机谁敢当，吹毛岂轻试。","贝叶启千函，木榻脱双履。","惟应胜壁观，悠悠度年岁。"]},{"t":"题蒙庵为黄石谷赋","f":"五言古诗","c":["东南有高丘，下临万家邑。","汪洋浃春润，沃衍盛秋入。","群山若浪波，起伏翠重袭。","灵运好奇险，高平罕相及。","幽人园绮间，周览度原隰。","随山导清泉，积石拾层级。","结庵以蒙名，果行信所执。","良时一来游，朔月九交十。","门当星斗高，陇卧风雨湿。","一川灯火归，宾从杂车笠。","登高愧能赋，腾身竦山立。"]},{"t":"平江开元雪窗光禅师访予临川山中其归也予与宾客用一雨六月凉中宵大江满分韵送之不足予为继之而予分得一字","f":"五言古诗","c":["积雪何处高，蜀山最崷崒。","海东极孤绝，目送断鸿一。","徘徊桫椤树，宴坐但空室。","园果堕宿雨，当昼从定出。","八月露水繁，石钵满华蜜。","相会岂无因，分床便深密。"]},{"t":"秋山行旅图","f":"五言古诗","c":["春夏农务急，新凉事征游。","饭糗既盈橐，治丝亦催裘。","升高践白石，降观索轻舟。","试问将何之，结客趋神州。","珠光照连乘，宝剑珊瑚钩。","乘马垂苜蓿，纵目上高丘。","策名羽林郎，谈笑觅封侯。","太行何崔嵬，日暮摧回辀。","古木多悲风，长途使人愁。","羸骖见木末，足倦霜雪稠。","谷口何人耕，禾麻正盈畴。","出门不及里，酒馔相绸缪。","壮者酣以歌，期颐醉而休。","安知万里事，有此千岁忧。"]},{"t":"次韵太朴良友对何仙舟读书山中见怀之作","f":"五言古诗","c":["得谢荷休泽，消摇在岩阿。","结庐庇风雨，樊圃搴藤萝。","塞坐古人书，日夕犹咏歌。","追念少壮日，玩愒亦已多。","兢兢事补塞，奈此迟暮何。","美人百里内，邈若隔山河。","兴怀贻好音，缊藉三春花。","报言慎芳岁，卷石崇巍峨。"]},{"t":"刘忠肃公之四世孙中书舍人讳震孙之曾孙益之题其居曰云松巢予家与刘氏累世之契故为书忠肃公文集之首诗三篇并赋此与之","f":"七言古诗","c":["丞相昔游泰山顶，天风浩浩春昼永。","玉检微茫不可求，但觉灵霞熟丹鼎。","白日人间如水流，前代衣冠成古丘。","悠悠忧患何足计，直道千年横素秋。","徂徕之松数千尺，东连海上暮烟碧。","中书伟人如玉立，每向南风望东北。","浊世公子何翩翩，却忆匡庐还谪仙。","芙蓉出水耀初日，五色光新天为妍。","我今侨居庐阜侧，西视峨眉归未得。","岂无云锦晚相娱，月落终怀雪山白。","森森乔木鲁东家，河间礼乐更光华。","勿忘先世旧游处，吾秣尔马膏其车。"]},{"t":"空山歌","f":"七言古诗","c":["高空之山聂公宅，稚川作图才数尺。","秋天薄云千仞表，春雨乔林百年物。","忆昔侍郎镇成都，将佐盈庭宾客趋。","锦官城外笳鼓发，驷马桥边高盖车。","先庐旧在小东郭，丞相祠前同寂寞。","严公同访杜陵家，退之亦到淮西幕。","峨眉嵯峨久不归，江水娱人秋日晖。","坐看蓬莱变桑海，自古南城天下稀。","公子亲迎陈氏馆，我初至抚犹弱冠。","看君挥翰甚风流，岂想重逢鬓毛换。","君言中间一再来，数见先公胸次开。","莺花风雨必求友，水竹园林持酒杯。","嗟予晚岁始能退，宁有文章惊海内。","平生不受简书畏，故家高致君应最。","图中山色积翠浓，虽欲舍子将焉从。","蜀人相如最能赋，行倚山木歌高空。"]},{"t":"为燮玄圃题鳌溪春晓图","f":"七言古诗","c":["芙蓉山阳万家邑，石岭戴辙萦纡入。","溪水西行夜雨深，连村桑柘春云湿。","昔因荒迥少官府，日暮狐兔作人立。","自从置县二百年，稍有衣冠更俗习。","读书进士比舍闻，润屋黄金亦家给。","山中白日浮云多，负乘因仍足车笠。","燮侯世冑国勋旧，射策君门耻沿袭。","朱衣作监列星宿，远人岂意高轩及。","援琴不鼓书牒稀，弹铗无鱼宾客集。","绣衣使者停车见，黄堂大夫下床揖。","登高望远送飞鸿，揽辔骎骎度原隰。","人言桐乡人爱我，我爱桐乡重于邑。","画图千叠山木稠，茇舍萧条莫忘葺。"]},{"t":"题马竹所画","f":"七言律诗","c":["霜清木落江海空，一棹归来何处翁。","双松千岁如铁石，为尔回薄旋天风。","忆昔神龙剑所化，夕卧沧波弄明月。","望中冉冉云气生，直接银河上琼阙。"]},{"t":"藿元镇规模董北苑米南宫父子写山水云物殊有标致见示春江捕鱼图遂赋此","f":"七言律诗","c":["春江聚网万鱼急，渔人相欢鱼相泣。","负薪深山何处樵，利害相乘不相及。","海鸥冥冥秋影微，黄叶江南一棹归。","人间得失两无迹，不废山水含清晖。"]},{"t":"题村田乐图","f":"七言古诗","c":["尺素自是高唐物，瑩如秋水宜设色。","何人画此畎亩间，二三老人若相识。","茅屋萧条古树下，农务未殷牛在野。","或怜鸲鸲脱笼絷，或弄狝猴笑真假。","老翁政自如儿嬉，高髻襁负相扶持。","古时枌社祀田祖，移馔高亭随所宜。","抱瓮初来未贮酒，亦有生鹅宛延首。","村优竞携乐具至，犬怪鸡惊儿拍手。","拄杖出门欣见宾，杂花满庭生好春。","岁时无事得如此，击壤何必非尧民。","骑驴过桥殊矍铄，携具荒陂来赴约。","定知张果千岁人，游戏人间共杯酌。"]},{"t":"同开先南楚悦禅师观息斋画竹卷于崇仁普安寺煜公之禅室盖煜之师一初本公所藏也因记延祐甲寅息斋奉诏写嘉熙殿壁南楚与之同寓庆寿寺时予同为太常博士俯仰之间已为陈迹乃题其后云","f":"七言律诗","c":["嘉熙殿里春日长，集贤奉诏写苍筤。","迩来二十有五载，飘零残墨到江乡。","匡庐高人昔同住，每见挥毫凤鸾翥。","木枯石烂是何年？","修竹森森长春雨。"]},{"t":"柳塘野鸭","f":"七言古诗","c":["江南水退秋光浅，风柳参差万丝捲。","鸳鸯在梁凫在渚，荡荡扁舟去家远。","千艘转海古长策，白粲连江动秋色。","断蒲折苇野水阔，烂烂明星且将弋。","翠盘擎露夜深寒，玉色亭亭落月残。","太液池头黄鹄下，梦中曾见画中看。"]},{"t":"江贯道江山平远图","f":"七言古诗","c":["江参去世二百年，翰墨零落多无传。","人间几人写山水，谁能意在挥毫前。","昨见石林旧家物，春雷叠嶂初破墨。","我和叶诗颇豪放，三者相望都突兀。","险危易好平远难，如此千里数尺间。","高云舒卷非散地，丽日照耀皆名山。","我持美脯酒一斗，墨汁盈盘可濡首。","江生精神作此山，向山呼生当至否？","高秋银汉天无云，帷中泠然来夜分。","黄茅岭头华盖顶，画我独访浮丘君。"]},{"t":"为汪华玉题所藏长江万鸦图","f":"七言古诗","c":["云巢幽人爱江渚，抽思挥毫写横素。","波澜不惊潦水尽，秋气晶明绝烟雾。","征帆去棹不相袭，岸曲洲旋总堪赋。","孤村城市仅如蚁，百丈牵江直如缕。","萧萧木叶洞庭波，历历晴川汉阳树。","蒹葭宿雁天欲霜，丛苇寒鸦日云暮。","就中楼观何王宫，想见华年贮歌舞。","丹青倒景骇灵怪，粉黛含情怨幽阻。","青春游子憺忘归，白日泠风帐中语。","人间遗迹何足留，最惜精思堕尘土。","郭熙平远无散地，小米苍茫托天趣。","铦锋铓戟不破墨，刻画晶荧昔谁苦。","渤海细书艺文草，精绝戈波绝回互。","南唐后主万鸦图，点点晨光动毛羽。","昔年曾见今目昏，虽复逢之亦难睹。","汪侯此卷出故家，相示摩挲极愁予。","香奁犀轴见者稀，谩录馀情示来者。"]},{"t":"题渔村图","f":"七言古诗","c":["黄叶江南何处村，渔翁三两坐槐根。","隔溪相就一烟棹，老妪具炊双瓦盆。","霜前渔官未竭泽，蟹中抱黄鲤肪白。","已烹甘瓠当晨餐，更撷寒蔬共萑席。","垂竿何人无意来，晚风落叶何毰毸。","了无得失动微念，况有兴亡生远哀。","忆昔采芝有园绮，犹被留侯迫之起。","莫将名姓落人间，随此横图卷秋水。"]},{"t":"题韩干画马","f":"七言古诗","c":["韩生观马十二闲，时写一二传人间。","坡翁尝来伯时宅，见此遗迹开衰颜。","前行如云尘不动，后者追风绝飞鞚。","昔人能事已可能，始觉赏识非虚讽。","昔观秘府韩绝少，得见龙眠已惊倒。","使人读诗如见画，人中岂复生坡老。","五云之中天上奇，代产名驹天子骑。","神明尚令后古见，莫叹韩生非画师。"]},{"t":"题秦虢二夫人承召游华清宫图","f":"曲","c":["贵人并鞚如轻鸿，承恩驰入华清宫。","道途先不止行客，策蹇奔趋乌帽风。","奚囊堕地何足拾，岂有篇章浪相及。","画史当时妙墨传，光彩流动狂情急。","君不见白头拾遗徒步归，明眸皓齿事皆非。","朝天泥滑袖封事，高阁雨馀宫漏稀。"]},{"t":"玉隆宫所藏宋乾道宸翰云壑二字","f":"五言律诗","c":["昔者云归壑，天章自九重。","日华常映凤，山气尽成龙。","俯仰遗陈迹，高深俨德容。","飘然化春雨，结想在高松。"]},{"t":"寄三衢守马九皋","f":"五言律诗","c":["闻道三衢守，年丰郡事稀。","诗成花覆帽，酒列锦成围。","鹤发明春雪，貂裘对夕晖。","扁舟应载客，閒听洞箫归。"]},{"t":"寄题汪道士草亭","f":"五言律诗","c":["飞白妙娉婷，新题照草亭。","仙遗相鹤法，客借换鹅经。","雾雨归悬黍，风云护茯苓。","遥知春昼永，深坐养《黄庭》。"]},{"t":"闻雁","f":"五言律诗","c":["楼近煖云湿，夜深闻雁低。","声音灯外尽，羽翮月边迷。","冉冉白榆上，悠悠黄竹西。","应逢穆王骏，春草一长嘶。"]},{"t":"钱舜举画","f":"五言律诗","c":["一树花如雪，清明客未归。","坐看黄鸟并，梦作綵云飞。","翠袖寒犹薄，羊车过绝稀。","相如能作赋，月下卷春衣。"]},{"t":"山水图","f":"五言律诗","c":["汎舟桑落浦，望见香炉峰。","野水常敧树，山云不碍钟。","桃源携客觅，松径与僧逢。","为托荆关辈，添予九节筇。"]},{"t":"题马竹所画","f":"五言律诗","c":["老树依江岸，归舟傍钓竿。","水花看晚净，风叶识天寒。","雁字来千里，鱼羹付一餐。","远山青可隐，日下是长安。"]},{"t":"送客北门晨登山木阁","f":"五言律诗","c":["晨登山木阁，零雨煖于春。","溪水解留客，梅花偏照人。","秫香知酒熟，市远觉民淳。","此地堪娱老，惟愁度水频。"]},{"t":"仙游道士余岫云为从珠溪余隐士求得华山下黄茅冈一曲规作丹室喜而赋之不觉五首 其一","f":"七言律诗","c":["华山东下有茅冈，云是毛公旧隐场。","清露尚馀丹满臼，白云今许草为堂。","冬凭野烧开畬陇，春托山雷净石床。","从此便为千载计，洞天先拜紫玄章。"]},{"t":"仙游道士余岫云为从珠溪余隐士求得华山下黄茅冈一曲规作丹室喜而赋之不觉五首 其二","f":"七言律诗","c":["茅冈地主古醇儒，乞我冈头作隐居。","岭上閒云从管领，涧中流水听开除。","刀耕火种从兹始，雨笠风瓢便有馀。","自古诗人多会合，浮丘毛氏不愁予。"]},{"t":"仙游道士余岫云为从珠溪余隐士求得华山下黄茅冈一曲规作丹室喜而赋之不觉五首 其三","f":"七言律诗","c":["石人屹立古仙坛，双涧交流拱一盘。","临水种松须匼匝，就中作室要宽安。","洞经即日脩真诀，玉臼逢春浴旧丹。","却恐山中添故事，题诗莫与世传看。"]},{"t":"仙游道士余岫云为从珠溪余隐士求得华山下黄茅冈一曲规作丹室喜而赋之不觉五首 其四","f":"七言律诗","c":["仙游办得茅千束，华盖须分屋数间。","微咏玉经忘我老，谩调金鼎胜于閒。","龙雷变化从舒卷，鹤露清寒自往还。","何似绮园诸老者，采芝初不离南山。"]},{"t":"仙游道士余岫云为从珠溪余隐士求得华山下黄茅冈一曲规作丹室喜而赋之不觉五首 其五","f":"七言律诗","c":["茅冈初割一溪云，玄契华阳旧隐文。","谒简自题香案吏，封章先报大茅君。","种成和露桃千树，借与摩霄鹤数群。","便是宸清真洞府，不烦梦想托纷纭。"]},{"t":"抚郡天宁明极觉讲主陪敬斋监郡奉祠华盖特有高咏三读敬叹仆偶共清游辄复次韵衰退不工聊资笑粲","f":"七言律诗","c":["三峰宫殿接新桥，十月长斋陟翠峣。","朝步仍垂苍玉佩，登歌还引紫琼箫。","千枝绛蜡连虹贯，五色香云向日飘。","赖有高人陪后乘，轻清诗句似参寥。"]},{"t":"秋日同朋游北塔山","f":"七言律诗","c":["归田多病故人疏，好客相逢乐有馀。","老去深杯那解饮，诗成大字尚能书。","门生去上青骢马，道士归骑赤鲤鱼。","如此馀閒多乐事，谁能七十始悬车。"]},{"t":"送易用昭","f":"七言律诗","c":["诗成长是倩人书，最爱东家织翠裾。","远树断云春雨外，华星明月晚凉初。","满窗柿叶题都遍，短帽梅花画不如。","莫向墨池成久别，鹅群还欲谢崇虚。"]},{"t":"集自郡城归溪山翁寄诗并和申字韵垂教依韵再呈殊愧迟拙 其一","f":"七言律诗","c":["暮春长日雨兼风，买得江船未及东。","出郭故人邀杜老，辍耕田父讶庞公。","谩从修禊忘溪曲，何用安车遍洛中。","旦起紫芝行复长，咏归先与谢崆峒。"]},{"t":"集自郡城归溪山翁寄诗并和申字韵垂教依韵再呈殊愧迟拙 其二","f":"七言律诗","c":["待客花阴午过申，茶香榆火一时新。","千竿嫩绿摇轻暑，数萼馀红坠晚春。","坐忆云林行道迹，梦游仙岛意生身。","连根分种如冰雪，来向清池对玉真。"]},{"t":"己卯腊八日雪为魏伯亮赋","f":"七言律诗","c":["官桥柳外雪飞绵，客舍樽前急管弦。","僧粥晓分惊腊日，猎围晨出忆残年。","白头长与青山对，华屋谁为翠黛怜。","惟有寒梅能老大，独将清艳向江天。"]},{"t":"某与胡伯友书问疏阔稍久因楚石藏主待谒翘仰高谊赋寄此诗","f":"七言律诗","c":["乔木千章万壑秋，使君清兴在危楼。","星沈夜水神鱼化，霜落寒汀宿雁留。","红袖乌丝酣楚客，画屏银烛看吴钩。","不知肯著枯藤杖，采采芙蓉涉远洲。"]},{"t":"赠楚石藏主谒饶心道六有先生","f":"七言律诗","c":["不识南塘第几桥，翠楼华屋上岧峣。","古文独许扬雄识，幽兴谁为杜甫邀。","伐木春声生涧谷，涉江秋影荡兰苕。","散花如雨携双履，解与高人话寂寥。"]},{"t":"缙山张君荣字仲华来丞抚之崇仁历两政六年心平气顺上下相安如一日虽有远役重劳亦无阙事甚可称也予之閒居相爱如故旧每怀扈从东道往来缙山道中见其风土之胜民俗之美未尝不谈道以为乐于其受代调官京师因记之以诗而与之别明年进秩南来观旧治父老儿童相迎于东门之外又当歌此以为一笑之欢也","f":"七言律诗","c":["昔从时巡出缙山，翠畦绿树画图间。","驱车百折龙门险，载笔千峰虎帐閒。","麦粉劝尝银缕熟，粱炊持献玉浆还。","道旁父老应常好，为说乡风一破颜。"]},{"t":"送抚郡经历海朝宗调官","f":"七言律诗","c":["馆阁论思拜命新，风云近接属车尘。","受釐宣室多清夜，奏赋甘泉是暮春。","雨过落花行处少，日移高树坐来频。","知君此日行吟思，骢马封章又避人。"]},{"t":"东坡墨竹","f":"七言律诗","c":["扁舟忆上浣花溪，风雨横江万竹低。","石室归来秋似水，峨眉相对醉如泥。","春雷翻石蛟龙起，夕照穿林鸟雀栖。","二老何年重会面，为挥浓墨写凄迷。"]},{"t":"白云间上人度夏","f":"七言律诗","c":["白云长傍太湖飞，忽向西江度钓矶。","彭泽小龙邀共饭，湖阳迁客忆留衣。","笋因春雨朝朝吃，橘待秋霜颗颗肥。","我自本名无所住，经函松下共柴扉。"]},{"t":"答甘允从寄海东白纻","f":"七言律诗","c":["海国綀衣雪色明，寄将千里见高情。","著随野鹤浑相称，行近沙鸥亦不惊。","江露满船歌醉起，炉烟携袖忆诗成。","秋风游子偏愁予，谁采芙蓉共晚晴。"]},{"t":"孙宰金碧山水","f":"七言律诗","c":["昔代香山避暑宫，中天积翠立芙蓉。","云生金水三春柳，露滴银床五粒松。","飞瀑桥长通窈窕，断堤人倦立从容。","旧时行处今看画，烟雨楼台晚更浓。"]},{"t":"甲戌四月十七日至临川冲云寺祝圣寿斋罢为赋此诗","f":"七言律诗","c":["郭西寺门双石头，水槛相对林塘幽。","白花过雨落松暝，黄鸟隔溪鸣麦秋。","衰朽虚蒙宣室问，淹迟实爱小山留。","为贪佛日同僧话，满袖天香念旧游。"]},{"t":"蜀人刘梦良效杨补之掀蓬图","f":"七言律诗","c":["锦屏山下花如锦，却爱清江野水边。","放笔岂能无直干，掀篷方欲斗清妍。","最怜半面敧歌扇，更笑轻身障舞筵。","君看上林千树雪，繁枝何处独娟娟。"]},{"t":"答钱翼之","f":"七言律诗","c":["吴郡名书盛有唐，流传风致到钱郎。","闭门三月梨花雨，遍写千林柿叶霜。","客看旧题惊岁月，僧将新句度江乡。","莫愁茅舍淹留久，秋菊春兰各自芳。"]},{"t":"柯敬仲画古木疏篁","f":"七言律诗","c":["不见丹丘四五年，幽篁古木更苍然。","蒹葭霜露风连海，翡翠兰苕月在川。","忆昔画图天上作，每题诗句世间传。","前村深雪谁高卧，亦有晴虹贯夜船。"]},{"t":"李伯宗录诗","f":"七言律诗","c":["老去逢春祇谩吟，敢烦綵笔为追寻。","玉堂天上成尘梦，茅舍山中称野心。","万里云霄归鸟尽，孤村风雨落花深。","文章传世知何用，空使高情慨古今。"]},{"t":"题汪华玉子昂兰石二首 其一","f":"五言绝句","c":["海内出珊瑚，枝撑碧月孤。","鲛人拾翠羽，泣露得明珠。"]},{"t":"题汪华玉子昂兰石二首 其二","f":"五言绝句","c":["参差不可吹，纫佩寄远道。","遂令如石心，岁晚永相好。"]},{"t":"春妍带雪图","f":"五言绝句","c":["玉茗深宫里，春妍带雪残。","可怜五色羽，相并不知寒。"]},{"t":"题饶世英所藏钱舜举四季花木海棠","f":"五言绝句","c":["睡起多情思，依稀见太真。","一枝红泪湿，似忆故宫春。"]},{"t":"黄蜀葵","f":"五言绝句","c":["花萼立清晨，鹅黄向日新。","金杯承玉露，偏醉蜀乡人。"]},{"t":"芙蓉","f":"五言绝句","c":["丹霞覆苑洲，公子夜来游。","终宴清露冷，折花登彩舟。"]},{"t":"家茶","f":"五言绝句","c":["万木老空山，花开绿萼间。","素妆风雪里，不作少年颜。"]},{"t":"题饶世英所藏孤鹤图","f":"七言绝句","c":["海风吹月忆危巢，清夜梳翎雪堕坳。","仙客不知犹是画，每听长唳向松梢。"]},{"t":"赠朱万初二首 其一","f":"七言绝句","c":["珥貂鸣佩入明光，新墨初成进御床。","草野小臣春梦短，犹怀染翰侍君王。"]},{"t":"赠朱万初二首 其二","f":"七言绝句","c":["延阁晨趋接佩声，又纡朱绂向江城。","丹心要似东阳水，酿作官壶彻底清。"]},{"t":"雪后偶成","f":"七言绝句","c":["晓来残雪在陂陁，远似羊群或似鹅。","忆踏春泥看柳色，驼裘貂帽度冰河。"]},{"t":"自赞题白云求陈可复所写像","f":"七言绝句","c":["归来江上一身轻，野服初成拄杖行。","祗好白云相伴住，天台庐阜听松声。"]},{"t":"子昂竹","f":"七言绝句","c":["忆昔吴兴写竹枝，满堂宾客动秋思。","诸公老去风流尽，相对茶烟飏鬓丝。"]},{"t":"八骏图","f":"七言绝句","c":["瑶池积雪与天平，西极空闻八骏名。","玉殿重来人世换，萧萧苜蓿汉宫城。"]},{"t":"中秋前偶赋四首 其一","f":"七言绝句","c":["一室萧然绝蔽亏，桂香初发自先知。","已无热恼仍无梦，坐到空林月落时。"]},{"t":"中秋前偶赋四首 其二","f":"七言绝句","c":["空林月落大如盘，鸡犬无声晓气寒。","童子儗谋朝一食，玉杯盛得露漙漙。"]},{"t":"中秋前偶赋四首 其三","f":"七言绝句","c":["一杯浓露滑如饴，灌溉清凉可疗饥。","毕力石田嗟已晚，空山何处采灵芝？"]},{"t":"中秋前偶赋四首 其四","f":"七言绝句","c":["采芝不觉过前山，偶答樵歌莫却还。","人影自行残照外，雨云先入翠微间。"]},{"t":"次韵答鲁子晕参政二首 其一","f":"七言绝句","c":["海风吹雨散晨曦，纨扇高堂两鬓丝。","想见东南宾客盛，临江酾酒看潮时。"]},{"t":"次韵答鲁子晕参政二首 其二","f":"七言绝句","c":["病鹤前年下玉京，空巢聊寄一毛轻。","白云千载悠悠外，自照寒溪野水清。"]},{"t":"玉龙图","f":"七言绝句","c":["贝阙澄澄海月生，水晶帘影接空明。","鲛绡剪得霓裳就，却拥冰髯上太清。"]},{"t":"赠閒白云","f":"七言绝句","c":["白云东去又经春，每想飞鸿到水滨。","几个遮山松树子，凭君洒雨洗埃尘。"]},{"t":"无题","f":"七言绝句","c":["贝阙珠宫夜不眠，露华浩浩月娟娟。","不应又作人间梦，窈窕吹箫度碧烟。"]},{"t":"闻机杼","f":"七言绝句","c":["咿哑机杼隔林幽，梦觉江湖忆旧游。","满地月明凉似水，数声柔橹过扬州。"]},{"t":"溪桥踏雪","f":"七言绝句","c":["万竹孤亭积雪明，冲寒先到寄高情。","过桥不是寻常客，共听空山裂帛声。"]},{"t":"赋范德机诗后","f":"七言绝句","c":["玉堂妙笔交游尽，投老江南隔死生。","最忆崖州相忆处，华星孤月海波清。"]},{"t":"送程以文兼简揭曼硕","f":"七言绝句","c":["故人不肯宿山家，半夜驱车踏月华。","寄语旁人休大笑，诗成端的向谁誇。"]},{"t":"癸酉岁晚留上方观三首 其一","f":"七言绝句","c":["灯前自了读残经，风入疏帘月入棂。","坐到夜深谁是伴，数枝梅萼一铜瓶。"]},{"t":"癸酉岁晚留上方观三首 其二","f":"七言绝句","c":["偶行幽径岂寻春，忽见丛兰紫茁新。","幸自林深可终日，莫将香引路行人。"]},{"t":"癸酉岁晚留上方观三首 其三","f":"七言绝句","c":["山中积雪到檐端，独对篝灯坐夜阑。","不是梅花心似铁，如何禁得许多寒。"]},{"t":"田舍","f":"七言绝句","c":["晨昏车马乱云烟，花下追游亦偶然。","百舌无声春亦去，萧萧田舍日高眠。"]},{"t":"别燮玄圃后重寄","f":"七言绝句","c":["郭西山路有寒梅，想见临行首重回。","夜听雨声知水长，满船明月几时开？"]},{"t":"古桧","f":"七言绝句","c":["根到深泉石作身，疏疏香叶不知春。","海波不动天风远，千岁寒蛟作老人。"]},{"t":"万户张公庙堂诗","f":"曲","c":["于赫世皇，并用豪杰。","一定宇内，櫜厥戈甲。","既久既安，成宗继之。","祖功莫加，道在守持。","狂夫兴谋，以动相国。","曰昔祖宗，咸尚战克。","万方悉来，史皆前能。","我独无名，曷称继承。","蠢彼西南，翳丛负固。","聚落八百，各统女妇。","人强善骄，马具竞豪。","豢豕于牢，黄金饰槽。","取而有之，富可足用。","赫乎功多，以世智勇。","相臣以闻，天子曰嘻！","有是言哉，汝其试之。","狂谋既售，谏言不入。","既赋军实，弓钺仍戢。","馈饟启行，万里骚然。","饥危蹈毒，未战已捐。","番番名将，天子爪士。","镇于江浒，天子所使。","狂夫忌之，承制驱之。","讵思国谋，徒逞厥私。","将军慨言，死我臣职。","可陷者身，不陷吾直。","见制鄙庸，岂我召凶。","心知无还，况冀立功。","与其矫诬，死彼狂手。","孰与奋击，不丧吾守。","孤旅转战，身入不回。","杀戮既多，身卒死之。","三军失声，万士丧气。","孰明公心，君门万重。","裹革东归，遥遥江壖。","部曲候迎，悲风旆缠。","民怀其忠，士感其义。","虎奋鹰扬，如见其至。","卜庙得吉，东望际海。","神来妥之，有永无坏。","狂夫辱国，天子震怒。","立呼狂竖，斩以大斧。","狂罪则诛，死事奈何。","褒封哀荣，百世不磨。","岂惟不磨，元嗣御史。","既有兄弟，又多孙子。","奕奕勋门，秩秩良材。","天之报忠，岂有涯哉。"]},{"t":"金人出塞图","f":"七言古诗","c":["海风吹沙如捲涛，高为陁碛深为壕。","筑垒其上严周遭，名王专居气振豪。","肉食湩饮田为遨，八月草白风飕颾。","马食草实轻骨毛，加弦试弓复置櫜。","今日不乐心慅慅，什什伍伍呼其曹。","银黄兔鹘明绣袍，鹧鸪小管随鸣鼗。","背孤向虚出北皋，海东之鸷王不骄。","锦鞲金镞红绒绦，按习久蓄思一超。","是时皛清天翳绝，鴐鹅东来云帖帖。","去地万仞天一瞥，离娄属望目力竭。","微如闻音鸷一掣，束身直上不回折。","遂使孤飞一片雪，顷刻平芜洒毛血。","争誇得隽顿足悦，挂兔县狼何足说。","旌旗先归向城阙，落日悲风起萧屑。","烟尘满城鼓微咽，大酋要王具甘歠。","王亦欣然沃焦热，阏支出迎骑小驖，琵琶两姬红颧颊。","歌舞迭进醉烛灭，穹庐斜转氍毹月。"]},{"t":"题花鸟图","f":"七言律诗","c":["吴中女儿颜色好，洗面看花花为悄。","调朱弄粉不自施，写作窗间雪衣鸟。","绿窗沈沈春昼迟，半生心事花鸟知。","花残鸟去人不归，细雨梅酸愁画眉。"]},{"t":"次韵马伯庸少监四首 其一","f":"五言律诗","c":["仍岁从巡幸，山川识重临。","讲帏来济济，驰道止骎骎。","五月衣裘薄，诸生坐席深。","归耕何待老，莫问二疏金。"]},{"t":"次韵马伯庸少监四首 其二","f":"五言律诗","c":["移跸宫城曙，烟花绕阁重。","来王俱属籍，称使不传烽。","赐席还亲问，囊书更手封。","恐烦宣室召，视日转苍龙。"]},{"t":"次韵马伯庸少监四首 其三","f":"五言律诗","c":["臣甫多愁思，长歌拜杜鹃。","凿崖通阁道，积水放楼船。","惆怅霜横野，栖迟雪满颠。","经行看宿草，碧色自年年。"]},{"t":"次韵马伯庸少监四首 其四","f":"五言律诗","c":["太平知永日，渐老惜芳晨。","论说惭孤学，推扬负相臣。","退思常感慨，拜赐每逡巡。","郊薮多閒地，馀生托凤麟。"]},{"t":"奉别阿鲁灰东泉学士游瓯越","f":"五言律诗","c":["忆昔同经幄，春明下玉除。","挂冠俄去国，连舸总盛书。","笋脯尝红稻，莼羹斫白鱼。","莫言江海远，咫尺玉堂庐。"]},{"t":"题秋山图","f":"五言古诗","c":["峰迥留深隐，天清袭素袍。","栖身断人迹，游目送鸿毛。","树挂栖厓鸷，藤悬饮子猱。","龙眠石涧冷，虎撼树根牢。","木客吟时共，山樵弈处遭。","浮云过水尽，孤月挟霜高。","羽使来三岛，胎仙舞九皋。","左招玉斧饮，右揽赤松遨。","空色收寥廓，虚声起绎骚。","弹琴遗古散，载酒棹轻舠。","遂向图中见，谁能世外逃。","乘槎几月至，一泛九秋涛。"]},{"t":"送朱生南归","f":"七言律诗","c":["喜子南归盱水上，经过为我问临川。","几家橘柚霜垂屋，何处蒹葭月满船。","应有交游怜远道，试从父老说丰年。","寒机早晚成春服，一一平安报日边。"]},{"t":"归蜀","f":"七言律诗","c":["我到成都住五日，驷马桥下春水生。","过江相送荷主意，还乡不留非我情。","鸬鹚轻筏下溪足，鹦鹉小窗呼客名。","赖得郫筒酒易醉，夜深冲雨汉州城。"]},{"t":"自仁寿回成都","f":"七言律诗","c":["还乡思速去乡迟，王事相縻敢后期。","里父留看题壁字，山僧打送舍田碑。","胡桃筇竹南方要，卢橘枇杷上国知。","此日君亲俱在望，徘徊三顾欲何之。"]},{"t":"寄福建佥宪马叔惠","f":"七言律诗","c":["荔子枝头火齐红，高堂纨扇坐薰风。","湘筠簟冷鱼波合，海柏梁深燕雨通。","络纬岂知秋袂薄，扊扅长忆晓餐同。","禁城来看花如锦，谁道清霜解恼公。"]},{"t":"端午节饮客与赵伯高","f":"七言律诗","c":["龙沙冰井夏初融，簪笔长随避暑宫。","蜡烛烟轻留贾谊，铜盘露冷赐扬雄。","南村久病思求艾，北客多情问转蓬。","忽听满船歌《白苧》，翻疑昔梦倚春鸿。"]},{"t":"周昉画美人图","f":"七言律诗","c":["岛上云生日转櫩，海风吹面暮寒尖。","春明玉色遗芗泽，夜定珠光入镜奁。","织得鸳鸯成绿皱，教成鹦鹉啄红甜。","试令鼓瑟应无语，目断归帆思未忺。"]},{"t":"赋雪洲","f":"七言律诗","c":["江上经年忆雪多，长洲化作玉坡陀。","旧时射虎迷蹲石，薄暮归渔认拥蓑。","河伯作宫龙献璧，湘灵遗佩凤停梭。","凫鹥容与江花发，更待春来生水波。"]},{"t":"赠道士","f":"七言律诗","c":["神室谁开自洞微，紫烟为户玉为扉。","春容淡薄胎仙舞，夜景虚明脉望飞。","绕指风雷龙睡醒，满囊云锦虎驮归。","犹嫌长物烦闻见，更上高台一振衣。"]},{"t":"赠无尘道人","f":"七言律诗","c":["云雾为衣月作裳，天坛独自礼虚皇。","龙收古剑沈秋水，鹤识神丹起夜光。","金井有声惟坠露，玉阶无色乍凝霜。","无端下界松风动，又欲飘然上凤凰。"]},{"t":"玉华山","f":"七言律诗","c":["何处清江拥玉华，手题名榜寄仙家。","光凝石殿千年雪，影动银河八月槎。","藏药宝函腾玉气，说诗瑶席散天葩。","奎章阁吏无能赋，得似新官蔡少霞。"]},{"t":"王庶山水","f":"七言律诗","c":["蜀人偏爱蜀江山，图画苍茫咫尺间。","驷马桥边车盖合，百花潭上钓舟閒。","亦知杜甫贫能赋，应叹扬雄老不还。","花重锦官难得见，杜鹃啼处雨斑斑。"]},{"t":"画虎图赠真一先生","f":"七言律诗","c":["猎猎霜风木叶乾，月明曾过越王山。","青龙久待蟠仙鼎，赤豹相呼守帝关。","终岁采芝茅阜曲，丰年收谷杏林间。","谁家稚子能为御？","长与桃椎共往还。"]},{"t":"滕王阁","f":"七言律诗","c":["城头高阁插苍茫，百尺阑干背夕阳。","秋雨鱼龙非故物，春风蛱蝶是何王。","帆樯急急来彭蠡，车盖童童出豫章。","灯火夜归湖上路，隔篱呼酒说干将。"]},{"t":"京师秋夜","f":"五言绝句","c":["风竹撼秋声，天寒梦不成。","如何今夜月，偏照客窗明。"]},{"t":"王朋梅东凉亭图延祐中奉敕所作草也","f":"七言绝句","c":["滦水东流紫雾开，千门万户起崔嵬。","坡陀草色如波浪，长是銮舆六月来。"]},{"t":"丁卯礼部考试次韵二首 其一","f":"七言绝句","c":["忆昔坡头接锦袍，深堂披卷效微劳。","三年重得同清夜，宫烛风帘见月高。"]},{"t":"丁卯礼部考试次韵二首 其二","f":"七言绝句","c":["袍鹄锵锵赴晓闱，分庐陈艺别东西。","凭教红杏休开彻，早晚开关蹋雪泥。"]},{"t":"东家四时词四首 其一","f":"七言绝句","c":["临流洗砚见长身，白苧宽衣短葛巾。","纨扇自题新得句，水亭分送倚阑人。"]},{"t":"东家四时词四首 其二","f":"七言绝句","c":["摩挲旧赐碾龙团，紫磨无声玉井寒。","鹦鹉不知谁是客，学人言语近阑干。"]},{"t":"东家四时词四首 其三","f":"七言绝句","c":["澄波千顷拥高鬟，手折芙蓉月下还。","解忆高堂风露冷，衲衣先送碧云山。"]},{"t":"东家四时词四首 其四","f":"七言绝句","c":["贺雪宫门上表归，貂裘犹带六花飞。","海南新送收香鸟，转觉清寒入翠帷。"]},{"t":"赠傅与砺","f":"七言绝句","c":["水玉空青不易求，兰苕翡翠擅清秋。","才情岂是人间少，不到高唐梦未休。"]},{"t":"洪厓桥","f":"七言绝句","c":["澄江如练碧悠悠，一色芦花覆远洲。","无尽春天归雁急，月明寒影不曾留。"]},{"t":"题张希孟凝云石","f":"五言古诗","c":["海口不盈握，隤然如委云。","危岑集远思，虚窦栖微熏。","天高泰华断，日出香炉分。","几研袭清润，文章互絪缊。","潜雷起神谷，震惊天上闻。","亟视恐无及，化为九龙文。"]},{"t":"朱秀之杞菊轩","f":"五言古诗","c":["高轩何所植，杞菊交根枝。","紫实既秋熟，黄花亦晚滋。","嘉名信共爱，何以疗予饥。","此邦号富庶，士贾志怀资。","萧条山石间，谁复见茕嫠。","遗脱兼并馀，椎剥无完肌。","纵彼百亩受，岂得安耘耔。","种此顷步内，庶无征夺思。","采撷勿违节，烹芼贵有宜。","三咽可千岁，逍遥奉天随。"]},{"t":"送豫章熊太古兼寄苏伯修参政","f":"五言古诗","c":["豫章有家学，礼乐不见收。","为养不择禄，凄凉向炎州。","揽结桂树枝，谁为玉雪谋。","十年一再见，我老君白头。","古剑光陆离，系以珊瑚钩。","激昂文史间，未愧班马俦。","苏君天下士，定价琳琅球。","江汉方渺然，为我观素秋。","长吟以相送，明月在高楼。"]},{"t":"李伯时九歌图","f":"七言古诗","c":["太乙神君号东皇，玉质要妙含和阳。","生生气始通微茫，绵绵蒸空神中央。","浮英上罗文天章，覆冒下满谷与坑。","旁塞无间灵无方，灵来乘柔往乘刚。","湘君夫人镇相望，清温静好非淫伤。","司命元老元气昌，手执藜杖色老苍。","历劫寿命不可量，少君之寿同其长。","离无异体合有常，出入万化终不亡。","晶明发晨上榑桑，海天赫赫真金芒。","质鍊不灭长垂光，河源混混流汤汤。","伯也坐视无迎将，千古万古何堂堂。","彼幽为厉为强梁，朝狸暮豹方鸱张。","精魂熠耀志意荒，招之不反巫无良。","屈生作歌沈九湘，世人传声罕寻详。","祝融仙子调玄黄，九神出图百怪藏。","不信请视虞公章。"]},{"t":"送吕教授还临川","f":"七言古诗","c":["黄金作台留好客，好客不留秋月白。","东风吹雪满衣襟，却赋长歌送行客。","辽东之山医巫闾，六月五月雪不除。","昨朝遣使降香去，五尺冰上行飞车。","知君江上惯舟楫，快马如龙亦徒设。","束取来时一卷书，还向江波对明月。","我本蜀人随水来，结屋与子相邻隈。","白发京尘不归去，临风相送兴悠哉。"]},{"t":"城南春晓图","f":"七言古诗","c":["天台先生有山癖，卧起无山朝不食。","几年骑马听朝鸡，磊磈诸峰拄胸臆。","陈生受意不受辞，竟拈秃笔为扫之。","既安楼观对奇石，复著梁栈横清漪。","游吾旧游钓吾钓，隔林彷佛闻幽鸟。","琼台何处无桃花，此是城南暮春晓。","夜来天子传诏呼，先生直上銮坡趋。","盘盘回复一万里，无限好山并好水。","如从岛上见陈生，尽写归来画堂里。"]},{"t":"金马图","f":"七言律诗","c":["贾胡自骑千金马，解囊小憩荒城下。","平原无树起秋风，梦到阴山雪横野。","太平疆宇大无外，外户连城无闭夜。","不然安有独行人，怀宝安眠如画者。"]},{"t":"刷马歌","f":"曲","c":["天马之来大宛国，汉帝心驰渥洼域。","贰师兵甲费如山，毛骨权奇不多得。","世祖开基肇太平，昔日大宛俱拱北。","如云之马西北来，飞控惊尘遍南陌。","豢养年深生息蕃，即今诏刷无遗迹。","青丝络头千万辈，戢戢骈头死槽枥。","一程瘏毒一程愁，比到燕山肥者瘠。","吾观天厩十二闲，五花成队春斑斑。","监官喂养盛刍豆，年年骑去居庸关。","圣朝谁信多盗贼，却虑骑气藏凶奸。","驽骀尽从天上去，骅骝岂得留人间。","汉人南人窘徒步，道路相从俱厚颜。","我今已是倦游者，东家蹇驴何必借。","布袜青鞋取次行，正喜不遭官长骂。","乡里健儿弓弩手，诏许征鞍常稳跨。","岭南烽火乱者谁？","何事至今犹梗化。","君不见汉文皇帝承平时，千里之马将安之。","又不见项王一骑乌江渡，到头不识阴陵路。"]},{"t":"次韵叶宾月山居十首 其一","f":"五言律诗","c":["冰泮溪流碧，云生岛屿红。","轻阴残梦里，远树乱愁中。","鸥外兼晴絮，莺边共晚风。","地偏山气近，霏霭湿房栊。"]},{"t":"次韵叶宾月山居十首 其二","f":"五言律诗","c":["露冷天光逼，溪澄夜影圆。","水花含窈窕，山吹纵清绵。","为觅洪崖侣，重寻赤壁船。","翻愁孤鹤外，回互万山连。"]},{"t":"次韵叶宾月山居十首 其三","f":"五言律诗","c":["绿琐依松润，缃帘乱藓斑。","吹笙花下散，飞燕雨中还。","有客归谋酒，无言卧看山。","春禽忽相唤，深树两关关。"]},{"t":"次韵叶宾月山居十首 其四","f":"五言律诗","c":["风日宜芳岁，烟霞乐燕居。","坐深閒看弈，烛冷静修书。","腊酝红生玉，春盘绿间蔬。","但须门有客，不问食无鱼。"]},{"t":"酬崔御史送熊掌","f":"五言律诗","c":["熊掌来东国，分甘到老夫。","鸾刀寒断节，翠釜煖柔肤。","兔脱中山醢，鱼藏丙穴腴。","藜肠浑未厌，玉食恐时须。"]},{"t":"代祀西岳答袁伯长王继学马伯庸三学士二首 其一","f":"七言律诗","c":["紫禁沈沈曙色低，奉祠群使已班齐。","承恩归院迷烟树，乘传开关蹋雪泥。","蹀躞共怜骑苑马，逶迤不若听朝鸡。","山川有事宁辞远，咫尺成都是国西。"]},{"t":"代祀西岳答袁伯长王继学马伯庸三学士二首 其二","f":"七言律诗","c":["栈道年年葺旧摧，已将平易履崔嵬。","经行关辅图中见，梦恋乡山马上来。","诸葛精神明似日，相如情思冷于灰。","重思亲舍犹南国，愿托江波去却回。"]},{"t":"张道士蜀山图","f":"七言律诗","c":["碧玉参天是蜀山，旧曾飞度历孱颜。","松风上接空歌外，萝月长悬合景间。","试剑丹崖秋隼疾，濯缨清涧夜龙閒。","君家虚靖归来日，冉冉蓬壶为忆还。"]},{"t":"从兄德观父与集同出荣州府君宋亡隐居不仕而殁集来吴门省墓从外亲临邛韩氏得兄遗迹有云我因国破家何在君为唇亡齿亦寒不知为谁作也抚诵不觉流涕因足成一章并发其幽潜之意云","f":"七言律诗","c":["我因国破家何在，君为唇亡齿亦寒。","南渡岂殊唐社稷，中原不改汉衣冠。","温温雨气吞残壁，泯泯江潮击坏栏。","万里不归天浩荡，沧波随意把渔竿。"]},{"t":"兴庆宫朝退次韵袁伯长见贻是日上加尊号礼成告谢集即东出奉祠斋宫","f":"七言律诗","c":["翠盖重重宝扇斜，从官穿柳散慈鸦。","过宫路远纡天步，上寿杯深阁雨花。","玉贯两虹通象锦，衣成五綵鍊云霞。","奉祠东出蓬莱道，春水凫鹥踏汉槎。"]},{"t":"游冈子原呈王学士","f":"七言律诗","c":["冈子原头春色浓，小车晨出看东风。","雨馀林润人乌好，日煖沙平我马同。","西引峰峦来座上，东瞻楼阁起天中。","咏归莫作匆匆晚，傥解相逢击壤翁。"]},{"t":"和李秋谷平章小车诗","f":"七言律诗","c":["雪晴宫草隐晴沙，相国朝天试帝车。","班马昼移温室树，鸣鸾晨度掖垣花。","搴帷每命贤俱载，趣驾频烦使至家。","此日龙门谁执御，拥经正履侍金华。"]},{"t":"次韵寄元复初","f":"七言律诗","c":["黄梁梦觉人千里，白璧归来月一缸。","尊酒几时忘北海，束书无路到东窗。","卧龙宛宛冰生壑，飞鹤翩翩雪洒江。","无限心期总寥落，秋风烟树引归幢。"]},{"t":"罗若川画松","f":"七言律诗","c":["暮春多雨昼冥冥，罗生画松当素屏。","老蛟化为剑气黑，白鹤下啄苔痕青。","传来日暮自篝火，梦入幽岩寻茯苓。","不遇胡僧露双脚，石函自了读残经。"]},{"t":"送胡士恭","f":"七言律诗","c":["十年京国擅才华，宰相频招载后车。","太液苍凉黄鹄羽，玄都烂熳碧桃花。","三清风露仙人馆，万里烟尘野老家。","拂拭旧题如隔世，华星明汉望归槎。"]},{"t":"舟泊安和阮宅次黄志高韵","f":"七言律诗","c":["十月东归下石泷，群公促膝共轻艭。","萧云故宅多乔木，阮籍清尊对暮江。","方驾肯来良马五，尺书先寄鲤鱼双。","欲求深隐何山曲，雪竹霜筠共一窗。"]},{"t":"赋文子方家筼筜亭竹影","f":"七言律诗","c":["数个筼筜一小亭，南窗承日印寒青。","水晶帘里珊瑚树，云母屏间翡翠翎。","却爱微风动萧瑟，翻疑薄暮倚娉婷。","凭君纵有鹅溪绢，莫与空花结定形。"]},{"t":"聂空山画扇","f":"曲","c":["客来山雨鸣涧，客去山翁醉眠。","花外晴云霭霭，竹边秋月娟娟。"]},{"t":"青山白云图","f":"七言绝句","c":["独向山中访隐君，行穷千涧水沄沄。","仙家更在空青外，只许人间礼白云。"]},{"t":"寄澄湛堂法师","f":"七言律诗","c":["月中桂子落岩阿，想有林间阅贝多。","持足地神衣拂石，献珠天女袜凌波。","香因结愿留龙受，水为烹茶唤虎驮。","寄到竹西无孔笛，吹成动地太平歌。"]},{"t":"送戴真人归越","f":"曲","c":["戴先生，日饮五斗醉不得，再饮一石不肯眠。","昨从桃源来，两袖携风烟。","长安道上小儿女，拍手拦道呼神仙。","马如游龙花如雨，蹴踏春秋作朝暮。","东方不作窗间戏，上帝还令海边去。","海边玉虹夜不收，贝宫珠阙皆蛟虬。","芝田玉树久相待，天上老仙那肯留。","戴先生，鉴湖之水三千丈，不可以鉴可以酿。","明朝亦脱锦袍去，与汝酣歌钓船上。"]},{"t":"三凤行赠海东之还江南","f":"曲","c":["海东之，兄弟三人如凤凰，胸臆羽翮皆文章，九年三入天门翔。","伯冲天，季惊人，一日四海皆知名。","东之之文五色云，见者眩晃生眵昏，三进三已之，了若耳不闻。","二人得之，喜未足云，东之不愠乃可尊。","束书江上还见亲，君子之乐乐足真。","君不见，匡庐之山酋萃而嵯峨，左界豫章渚，川汇为蠡鄱。","其阴浩浩源，导□经潜沱。","山气郁蓄不得去，上冲为紫盖，直与天相摩。","为云覆八极，为雨涨九河。","海东之，子能观山以成德，其进盖未可量也，偶尔小屈奈尔何！"]},{"t":"陈可复为予写戴笠图赋诗四首 其一","f":"七言律诗","c":["浮云满空无所依，高冈独行来者稀。","仙人冉冉遗松老，鸣鹿呦呦生草肥。","伐木远闻何处谷，顷筐近得故时薇。","山中雨来雾先合，此日先生戴笠归。"]},{"t":"陈可复为予写戴笠图赋诗四首 其二","f":"七言律诗","c":["南园多竹暑气微，始来结屋相因依。","挂巾石壁昼雾湿，沐发池水朝阳晞。","频年车马残霜雪，六月裳衣无绤絺。","邻翁问旧坐来久，此日先生戴笠归。"]},{"t":"陈可复为予写戴笠图赋诗四首 其三","f":"七言律诗","c":["老去悬车百虑灰，西风独爱菊花开。","田家酒熟邀皆去，茅屋诗成懒更裁。","欲及天清食沆瀣，要观日出上蓬莱。","赤松有约应相待，此日先生戴笠来。"]},{"t":"陈可复为予写戴笠图赋诗四首 其四","f":"七言律诗","c":["舍却乡人驷马车，老身全不要人扶。","云霄一羽山头杜，风雨孤村海上苏。","薄命长镵随积雪，多情破帽落轻乌。","莫围玉带垂朱绂，此是先生戴笠图。"]},{"t":"赠朱万初四首 其一","f":"七言绝句","c":["霜雪摧残涧壑非，深根千岁斧斤违。","寸心不逐飞烟化，还作玄云绕紫微。"]},{"t":"赠朱万初四首 其四","f":"七言绝句","c":["颇爱烧香是鼻尘，不应缘嗅又劳人。","方床石鼎过清昼，一缕山灵伴老身。"]},{"t":"次韵陈溪山红梅三首 其一","f":"七言律诗","c":["冰雪肌肤染绛云，岁寒林下对吟身。","先天气至浑如醉，初日光融转更新。","白发无能酬造化，金丹有道驻长春。","少年莫笑诗成处，倾倒相欢忘主宾。"]},{"t":"次韵陈溪山红梅三首 其二","f":"七言律诗","c":["春晓红生岛屿云，此中尽著两閒身。","不愁花笑发须白，漫诧人间句法新。","曲水徘徊天上日，深杯斟酌自家春。","繁英未落须频到，翠实金盘尚及宾。"]},{"t":"次韵陈溪山红梅三首 其三","f":"七言律诗","c":["雪后孤根发暖云，栽培本自一人身。","紫薇遗意成千古，绛萼深期又一新。","忠厚敢忘嘉树赋，冲和思广北枝春。","若为稚子犹堪教，三祝三加望大宾。"]},{"t":"书苏公帖后","f":"七言绝句","c":["苏木空闻蜀贾舟，袜材还复望袁州。","画叉犹是黄冈竹，细和陶诗饱即休。"]},{"t":"题赠叶梅野","f":"七言绝句","c":["昔结丝绚侍帝宸，青鞋今许向江津。","凭君先对梅花说，白发相看意更深。"]},{"t":"题胡徵君器之和陶轩","f":"曲","c":["春木晨荣，秋华夕滋。","流云行天，逝者如斯。","柴车葛巾，曷能归来？","我怀古人，徒诵其诗。","有美君子，尚友先觉。","靡觞不咏，无咏不属。","岂无他人，孰此追躅？","优哉游哉，君子之乐。","吾侪小人，力绌乃休。","犹可以驰，曷其停辀？","卷舒无闷，入圣实优。","敢以未成，窃方前修。","祖德之述，尚论其世。","我独何无，夙坠羁絷。","闻君赞歌，祇以生愧。","既曰知非，请勖馀岁。"]},{"t":"予少年过蓟门酒楼赋此题曰连十八书郡人疑其为吕洞宾作也谩记于此","f":"七言律诗","c":["耳目聪明一丈夫，飞行八极隘寰区。","剑吹白雪妖邪灭，袖拂春风槁朽苏。","气似酒酣双国士，情如花拥万天姝。","如今一去无消息，只有中天月影孤。"]},{"t":"句","f":"七言古诗","c":["帆樯星斗通南极，车盖风云拥豫章。"]},{"t":"己卯腊八日雪为魏伯亮赋 其二","f":"七言律诗","c":["漫空飞絮散轻绵，所异寒威欲折弦。","县令温存僵卧叟，词人解颂太平年。","剪云为叶烦相寄，种玉成田不受怜。","丹鼎温温千岁熟，乐天事业在知天。"]},{"t":"玉堂读卷","f":"七言律诗","c":["玉堂策士诏儒臣，御笔亲题墨色新。","省树坐移帘底日，宫壶驰赐殿头春。","虞庭制作夔龙盛，汉代文章董贾醇。","书阁暮年偏感遇，但歌天保播皇仁。"]},{"t":"谢书巢送宣和泸石砚","f":"七言律诗","c":["巢翁新得泸州砚，拂拭尘埃送老樵。","毁璧复完知故物，沈沙俄出认前朝。","毫翻夜雨天垂藻，墨泛春冰夜应潮。","恐召相如令草檄，为怀诸葛渡军遥。"]},{"t":"神凤琴","f":"七言律诗","c":["鸣鸟人间久不闻，遗弦欲托断琴纹。","曾看土鼓歌朝日，亦共陶尊醉夜分。","五色云中迎太乙，九疑山下望湘君。","采诗应被唐风谱，早晚楼船或祀汾。"]},{"t":"题故太子少傅翰林承旨李野斋幽居图","f":"七言律诗","c":["车盖归来托远林，鲁山崷崒鲁原深。","渔樵相识频分席，宾客时过共赐金。","百岁仪刑犹近古，五朝文物至于今。","披图想见登临地，松满徂徕起夕阴。"]},{"t":"赠升龙观主","f":"七言律诗","c":["榻前亲制先生号，赐与江南谢舜咨。","太华雪开天使下，少微星动史官知。","龙飞沧海留珠树，虎卧丹房守玉芝。","圣主无为千万寿，更应筑馆候安期。"]},{"t":"别国史院敕峰石","f":"七言律诗","c":["秋雨莓苔数丈身，文章曾见百年人。","吁嗟一代兴王盛，付托诸公制作新。","坰野有诗皆在鲁，泰山无刻更先秦。","凤麟一去无消息，空使驽骀愧后尘。"]},{"t":"题暖翠亭","f":"七言律诗","c":["老去惟思卧白云，一亭万竹喜初闻。","波回晓日鸳鸯并，沙散晴烟翡翠分。","把钓左泉归卫女，乘舟北渚望湘君。","谁能独采薇盈袖，却道高寒思不群。"]}]};